(328506,36501,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dos ... juegan en una alfombra, rodeados de amarillo.'::text,'amigos'::text,'amigo'::text,'amigos'::text,'Dos amigos juegan en una alfombra, rodeados de amarillo.'::text),
(328505,36501,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deux ... jouent sur un tapis, entourés de jaune.'::text,'amis'::text,'ami'::text,'amis'::text,'Deux amis jouent sur un tapis, entourés de jaune.'::text),
(328508,36501,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki ... bir halının üstünde oynuyor, etraflarında her yer sarı.'::text,'arkadaş'::text,'arkadaş'::text,'arkadaşlar'::text,'İki arkadaş bir halının üstünde oynuyor, etraflarında her yer sarı.'::text),
(328509,36501,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Két ... játszik egy szőnyegen, körülöttük minden sárga.'::text,'barát'::text,'barát'::text,'barát'::text,'Két barát játszik egy szőnyegen, körülöttük minden sárga.'::text),
(328512,36502,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gelb ist ... knallige Farbe, und sein Kleid ist absolut riesig!'::text,'eine'::text,'die'::text,'eine'::text,'Gelb ist eine knallige Farbe, und sein Kleid ist absolut riesig!'::text),
(328516,36502,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жовтий — це ... кричущий колір, а його сукня просто величезна!'::text,''::text,NULL::text,NULL::text,'Жовтий — це кричущий колір, а його сукня просто величезна!'::text),
(328515,36502,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El amarillo es ... color chillón, ¡y su vestido es absolutamente enorme!'::text,'un'::text,'el'::text,'un'::text,'El amarillo es un color chillón, ¡y su vestido es absolutamente enorme!'::text),
(328514,36502,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le jaune est ... couleur criarde, et sa robe est absolument énorme !'::text,'une'::text,'la'::text,'une'::text,'Le jaune est une couleur criarde, et sa robe est absolument énorme !'::text),
(328517,36502,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sarı ... çiğ renk ve elbisesi kesinlikle devasa!'::text,'bir'::text,NULL::text,'bir'::text,'Sarı bir çiğ renk ve elbisesi kesinlikle devasa!'::text),
(328518,36502,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sárga ... harsány szín, és a ruhája elképesztően hatalmas!'::text,'egy'::text,'a'::text,'egy'::text,'A sárga egy harsány szín, és a ruhája elképesztően hatalmas!'::text),
(328521,36503,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... gelbe Knochen ist für den Hund.'::text,'Dieser'::text,'Diese'::text,'Jene'::text,'Dieser gelbe Knochen ist für den Hund.'::text),
(328525,36503,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... жовта кістка для собаки.'::text,'Ця'::text,'Ці'::text,'Ті'::text,'Ця жовта кістка для собаки.'::text),
(328524,36503,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... hueso amarillo es para el perro.'::text,'Este'::text,'Estos'::text,'Esos'::text,'Este hueso amarillo es para el perro.'::text),
(328523,36503,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... os jaune est pour le chien.'::text,'Cet'::text,'Ces'::text,'Ces'::text,'Cet os jaune est pour le chien.'::text),
(328526,36503,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... sarı kemik köpek için.'::text,'Bu'::text,'Bu'::text,'Şu'::text,'Bu sarı kemik köpek için.'::text),
(328527,36503,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a sárga csont a kutyáé.'::text,'Ez'::text,'Ezek'::text,'Azok'::text,'Ez a sárga csont a kutyáé.'::text),
(328530,36504,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann trägt Gelb, und ... Hund trägt Rot.'::text,'sein'::text,'ihr'::text,'sein'::text,'Der Mann trägt Gelb, und sein Hund trägt Rot.'::text),
(328534,36504,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік у жовтому, а ... собака в червоному.'::text,'його'::text,'її'::text,'його'::text,'Чоловік у жовтому, а його собака в червоному.'::text),
(328533,36504,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre va de amarillo, y ... perro va de rojo.'::text,'su'::text,'su'::text,'su'::text,'El hombre va de amarillo, y su perro va de rojo.'::text),
(328532,36504,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme porte du jaune, et ... chien porte du rouge.'::text,'son'::text,'son'::text,'son'::text,'L''homme porte du jaune, et son chien porte du rouge.'::text),
(328535,36504,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam sarı giyiyor, ... köpeği de kırmızı giyiyor.'::text,'onun'::text,'onun'::text,'onun'::text,'Adam sarı giyiyor, onun köpeği de kırmızı giyiyor.'::text),
(328536,36504,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi sárgát visel, a ... pedig pirosat.'::text,'kutyája'::text,'kutyája'::text,'kutyája'::text,'A férfi sárgát visel, a kutyája pedig pirosat.'::text),
(328539,36505,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... trägt als Nächstes dieses Gelb? Der Hund, Alter.'::text,'Wer'::text,'Was'::text,'Wo'::text,'Wer trägt als Nächstes dieses Gelb? Der Hund, Alter.'::text),
(328543,36505,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... наступним одягне цей жовтий? Собака, бро.'::text,'Хто'::text,'Що'::text,'Де'::text,'Хто наступним одягне цей жовтий? Собака, бро.'::text),
(328542,36505,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... se va a poner este amarillo ahora? El perro, tío.'::text,'Quién'::text,'Qué'::text,'Dónde'::text,'¿Quién se va a poner este amarillo ahora? El perro, tío.'::text),
(328541,36505,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... va porter ce jaune après ? Le chien, frère.'::text,'Qui'::text,'Qu''est-ce qui'::text,'Où'::text,'Qui va porter ce jaune après ? Le chien, frère.'::text),
(328544,36505,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu sarıyı sırada ... giyecek? Köpek, kanka.'::text,'kim'::text,'ne'::text,'nerede'::text,'Bu sarıyı sırada kim giyecek? Köpek, kanka.'::text),
(328545,36505,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... fogja legközelebb ezt a sárgát hordani? A kutya, tesó.'::text,'Ki'::text,'Mi'::text,'Hol'::text,'Ki fogja legközelebb ezt a sárgát hordani? A kutya, tesó.'::text),
(328557,36507,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Farbbudget: Das Kleid hat ... Meter Gelb.'::text,'zwanzig'::text,'zwanzigste'::text,'zwanzigste'::text,'Farbbudget: Das Kleid hat zwanzig Meter Gelb.'::text),
(328561,36507,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бюджет кольору: сукня має ... метрів жовтого.'::text,'двадцять'::text,'двадцятий'::text,'двадцятий'::text,'Бюджет кольору: сукня має двадцять метрів жовтого.'::text),
(328560,36507,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Presupuesto de color: el vestido tiene ... metros de amarillo.'::text,'veinte'::text,'vigésimo'::text,'vigésimo'::text,'Presupuesto de color: el vestido tiene veinte metros de amarillo.'::text),
(328559,36507,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Budget couleur : la robe a ... mètres de jaune.'::text,'vingt'::text,'vingtième'::text,'vingtième'::text,'Budget couleur : la robe a vingt mètres de jaune.'::text),
(328562,36507,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Renk bütçesi: elbisede ... metre sarı var.'::text,'yirmi'::text,'yirminci'::text,'yirminci'::text,'Renk bütçesi: elbisede yirmi metre sarı var.'::text),
(328563,36507,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Színköltségvetés: a ruhán ... méter sárga van.'::text,'húsz'::text,'huszadik'::text,'huszadik'::text,'Színköltségvetés: a ruhán húsz méter sárga van.'::text),
(309009,34335,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... den Hund im Garten streicheln.'::text,'kann'::text,'kann'::text,'ist'::text,'Er kann den Hund im Garten streicheln.'::text),
(309013,34335,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... погладити собаку в саду.'::text,'може'::text,'може'::text,'є'::text,'Він може погладити собаку в саду.'::text),
(309012,34335,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... acariciar al perro en el jardín.'::text,'Puede'::text,'Puede'::text,'Está'::text,'Puede acariciar al perro en el jardín.'::text),
(309011,34335,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... caresser le chien dans le jardin.'::text,'peut'::text,'peut'::text,'est'::text,'Il peut caresser le chien dans le jardin.'::text),
(309014,34335,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köpeği bahçede ...'::text,'okşayabilir'::text,'okşayabilir'::text,NULL::text,'Köpeği bahçede okşayabilir.'::text),
(309015,34335,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a kutyát a kertben.'::text,'Megsimogathatja'::text,'Megsimogathatja'::text,'Van'::text,'Megsimogathatja a kutyát a kertben.'::text),
(309018,34336,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, morgen ... er den alten Hund wieder streicheln, ohne Scheiß.'::text,'wird'::text,'streichelt'::text,'streichelte'::text,'Yo, morgen wird er den alten Hund wieder streicheln, ohne Scheiß.'::text),
(309022,34336,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, завтра він знову ... того старого собаку, чесно.'::text,'погладить'::text,'гладить'::text,'гладив'::text,'Йо, завтра він знову погладить того старого собаку, чесно.'::text),
(309021,34336,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ey, mañana ... otra vez a ese perro viejo, en serio.'::text,'acariciará'::text,'acaricia'::text,'acarició'::text,'Ey, mañana acariciará otra vez a ese perro viejo, en serio.'::text),
(309020,34336,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, demain il ... encore ce vieux chien, sans mentir.'::text,'caressera'::text,'caresse'::text,'a caressé'::text,'Yo, demain il caressera encore ce vieux chien, sans mentir.'::text),
(309023,34336,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, yarın o yaşlı köpeği yine ..., yemin ederim.'::text,'okşayacak'::text,'okşar'::text,'okşadı'::text,'Kanka, yarın o yaşlı köpeği yine okşayacak, yemin ederim.'::text),
(309024,34336,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, holnap megint ... azt az öreg kutyát, komolyan.'::text,'meg fogja simogatni'::text,'megsimogatja'::text,'megsimogatta'::text,'Figyu, holnap megint meg fogja simogatni azt az öreg kutyát, komolyan.'::text),
(309036,34338,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bericht: Der Hund läuft mit 20 km/h, also ... er ihn streicheln.'::text,'wird'::text,'wird'::text,NULL::text,'Bericht: Der Hund läuft mit 20 km/h, also wird er ihn streicheln.'::text),
(309040,34338,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звіт: собака біжить зі швидкістю 20 км/год, тож він ... його погладити.'::text,'збирається'::text,'буде'::text,NULL::text,'Звіт: собака біжить зі швидкістю 20 км/год, тож він збирається його погладити.'::text),
(309039,34338,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Informe: el perro corre a 20 km/h, así que ... acariciarlo.'::text,'va a'::text,NULL::text,NULL::text,'Informe: el perro corre a 20 km/h, así que va a acariciarlo.'::text),
(309038,34338,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rapport : le chien court à 20 km/h, donc il ... le caresser.'::text,'va'::text,NULL::text,NULL::text,'Rapport : le chien court à 20 km/h, donc il va le caresser.'::text),
(309041,34338,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rapor: köpek saatte 20 km hızla koşuyor, bu yüzden onu ...'::text,'okşayacak'::text,'okşayacak'::text,NULL::text,'Rapor: köpek saatte 20 km hızla koşuyor, bu yüzden onu okşayacak.'::text),
(309042,34338,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jelentés: a kutya 20 km/h-val fut, ezért meg ... simogatni.'::text,'fogja'::text,'fogja'::text,NULL::text,'Jelentés: a kutya 20 km/h-val fut, ezért meg fogja simogatni.'::text),
(309045,34339,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er beschließt, dass er den Hund streicheln ..., weil er da ist.'::text,'muss'::text,'muss'::text,'sollte'::text,'Er beschließt, dass er den Hund streicheln muss, weil er da ist.'::text),
(309049,34339,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він вирішує, що ... погладити собаку, бо той тут.'::text,'мусить'::text,'має'::text,'мав би'::text,'Він вирішує, що мусить погладити собаку, бо той тут.'::text),
(309048,34339,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Decide que ... acariciar al perro, porque está ahí.'::text,'debe'::text,'tiene que'::text,'debería'::text,'Decide que debe acariciar al perro, porque está ahí.'::text),
(309047,34339,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il décide qu''il ... caresser le chien, parce qu''il est là.'::text,'doit'::text,'doit'::text,'devrait'::text,'Il décide qu''il doit caresser le chien, parce qu''il est là.'::text),
(309050,34339,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kararını veriyor: köpeği ..., çünkü orada.'::text,'okşamalı'::text,'okşamak zorunda'::text,'okşamalı'::text,'Kararını veriyor: köpeği okşamalı, çünkü orada.'::text),
(309051,34339,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy dönt, hogy meg ... simogatnia a kutyát, mert ott van.'::text,'kell'::text,'kell'::text,'kellene'::text,'Úgy dönt, hogy meg kell simogatnia a kutyát, mert ott van.'::text),
(309054,34340,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Hund ist alt, also ... er ihn sanft streicheln.'::text,'sollte'::text,'sollte'::text,'sollte'::text,'Der Hund ist alt, also sollte er ihn sanft streicheln.'::text),
(309058,34340,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Собака старий, тож він ... гладити його ніжно.'::text,'мав би'::text,'мав би'::text,'мав би'::text,'Собака старий, тож він мав би гладити його ніжно.'::text),
(309057,34340,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El perro es viejo, así que ... acariciarlo con suavidad.'::text,'debería'::text,'debería'::text,'debería'::text,'El perro es viejo, así que debería acariciarlo con suavidad.'::text),
(309056,34340,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chien est vieux, donc il ... le caresser doucement.'::text,'devrait'::text,'devrait'::text,'devrait'::text,'Le chien est vieux, donc il devrait le caresser doucement.'::text),
(309059,34340,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köpek yaşlı, bu yüzden onu nazikçe ...'::text,'okşamalı'::text,'okşamalı'::text,'okşamalı'::text,'Köpek yaşlı, bu yüzden onu nazikçe okşamalı.'::text),
(309060,34340,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kutya öreg, ezért gyengéden ... simogatnia.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'A kutya öreg, ezért gyengéden kellene simogatnia.'::text),
(309063,34341,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Hund rennt zu ihm, ... streichelt er ihn mit beiden Händen.'::text,'also'::text,'aber'::text,'weil'::text,'Der Hund rennt zu ihm, also streichelt er ihn mit beiden Händen.'::text),
(309067,34341,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Собака біжить до нього, ... він гладить його обома руками.'::text,'тому'::text,'але'::text,'бо'::text,'Собака біжить до нього, тому він гладить його обома руками.'::text),
(309066,34341,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El perro corre hacia él, ... él lo acaricia con las dos manos.'::text,'así que'::text,'pero'::text,'porque'::text,'El perro corre hacia él, así que él lo acaricia con las dos manos.'::text),
(309065,34341,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chien court vers lui, ... il le caresse des deux mains.'::text,'donc'::text,'mais'::text,'parce qu'''::text,'Le chien court vers lui, donc il le caresse des deux mains.'::text),
(309068,34341,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köpek ona doğru koşuyor, ... onu iki eliyle okşuyor.'::text,'bu yüzden'::text,'ama'::text,'çünkü'::text,'Köpek ona doğru koşuyor, bu yüzden onu iki eliyle okşuyor.'::text),
(309069,34341,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kutya odaszalad hozzá, ... ő két kézzel megsimogatja.'::text,'ezért'::text,'de'::text,'mert'::text,'A kutya odaszalad hozzá, ezért ő két kézzel megsimogatja.'::text),
(311475,34609,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gestern ... es den ganzen Tag, und die Party am Meer war ruiniert!'::text,'regnete'::text,'regnet'::text,NULL::text,'Gestern regnete es den ganzen Tag, und die Party am Meer war ruiniert!'::text),
(311479,34609,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учора ... весь день, і вечірка біля моря була зіпсована!'::text,'дощило'::text,'дощить'::text,NULL::text,'Учора дощило весь день, і вечірка біля моря була зіпсована!'::text),
(311478,34609,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ayer ... todo el día y la fiesta en el mar se arruinó!'::text,'llovió'::text,'llueve'::text,NULL::text,'¡Ayer llovió todo el día y la fiesta en el mar se arruinó!'::text),
(311477,34609,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... toute la journée hier, et la fête à la mer était gâchée !'::text,'a plu'::text,'pleut'::text,NULL::text,'Il a plu toute la journée hier, et la fête à la mer était gâchée !'::text),
(311480,34609,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün bütün gün yağmur ... ve deniz partisi mahvoldu!'::text,'yağdı'::text,'yağar'::text,NULL::text,'Dün bütün gün yağmur yağdı ve deniz partisi mahvoldu!'::text),
(311481,34609,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap egész nap ... az eső, és a tengerparti buli tönkrement!'::text,'esett'::text,'esik'::text,NULL::text,'Tegnap egész nap esett az eső, és a tengerparti buli tönkrement!'::text),
(311484,34610,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, anscheinend ... es gerade auf dem Meer.'::text,'regnet'::text,'regnet'::text,'regnet'::text,'Mädel, anscheinend regnet es gerade auf dem Meer.'::text),
(311488,34610,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, саме зараз над морем ...'::text,'дощить'::text,'дощить'::text,'дощить'::text,'Подруго, кажуть, саме зараз над морем дощить.'::text),
(311487,34610,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, parece que ahora mismo ... en el mar.'::text,'está lloviendo'::text,'llueve'::text,'está lloviendo'::text,'Tía, parece que ahora mismo está lloviendo en el mar.'::text),
(311486,34610,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment il ... sur la mer en ce moment.'::text,'est en train de pleuvoir'::text,'pleut'::text,'est en train de pleuvoir'::text,'Ma belle, apparemment il est en train de pleuvoir sur la mer en ce moment.'::text),
(311489,34610,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre şu an denizde yağmur ...'::text,'yağıyor'::text,'yağar'::text,'yağıyor'::text,'Kızım, duyduğuma göre şu an denizde yağmur yağıyor.'::text),
(311490,34610,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag épp most ... az eső a tengeren.'::text,'esik'::text,'esik'::text,'esik'::text,'Csajszi, állítólag épp most esik az eső a tengeren.'::text),
(311493,34611,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier regnet es nie, aber jetzt ... es auf der Bergstraße.'::text,'regnet'::text,'regnet'::text,NULL::text,'Hier regnet es nie, aber jetzt regnet es auf der Bergstraße.'::text),
(311497,34611,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тут ніколи не дощить, але зараз на гірській дорозі ...'::text,'дощить'::text,'дощить'::text,NULL::text,'Тут ніколи не дощить, але зараз на гірській дорозі дощить.'::text),
(311496,34611,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aquí nunca llueve, pero ahora ... en la carretera de montaña.'::text,'está lloviendo'::text,'llueve'::text,NULL::text,'Aquí nunca llueve, pero ahora está lloviendo en la carretera de montaña.'::text),
(311495,34611,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ne pleut jamais ici, mais là il ... sur la route de montagne.'::text,'est en train de pleuvoir'::text,'pleut'::text,NULL::text,'Il ne pleut jamais ici, mais là il est en train de pleuvoir sur la route de montagne.'::text),
(311498,34611,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Burada hiç yağmur yağmaz ama şimdi dağ yolunda yağmur ...'::text,'yağıyor'::text,'yağar'::text,NULL::text,'Burada hiç yağmur yağmaz ama şimdi dağ yolunda yağmur yağıyor.'::text),
(311499,34611,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Itt sosem esik, de most ... az eső a hegyi úton.'::text,'esik'::text,'esik'::text,NULL::text,'Itt sosem esik, de most esik az eső a hegyi úton.'::text),
(311511,34613,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deadline-Alarm: Um 17 Uhr ... es regnen.'::text,'wird'::text,'wird'::text,'regnet'::text,'Deadline-Alarm: Um 17 Uhr wird es regnen.'::text),
(311515,34613,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дедлайн-алерт: о 17:00 ...'::text,'збирається на дощ'::text,'піде дощ'::text,'іде дощ'::text,'Дедлайн-алерт: о 17:00 збирається на дощ.'::text),
(311514,34613,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alerta de plazo: a las 17:00 ...'::text,'va a llover'::text,'lloverá'::text,'llueve'::text,'Alerta de plazo: a las 17:00 va a llover.'::text),
(311513,34613,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alerte deadline : à 17 h, il ...'::text,'va pleuvoir'::text,'pleuvra'::text,'pleut'::text,'Alerte deadline : à 17 h, il va pleuvoir.'::text),
(311516,34613,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son tarih uyarısı: saat 17:00''de yağmur ...'::text,'yağacak'::text,'yağacak'::text,'yağar'::text,'Son tarih uyarısı: saat 17:00''de yağmur yağacak.'::text),
(311517,34613,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Határidő-riasztás: délután 5-kor ... az eső.'::text,'fog esni'::text,'fog esni'::text,'esik'::text,'Határidő-riasztás: délután 5-kor fog esni az eső.'::text),
(311520,34614,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Graue Wolken sind nasse Wolken, also ... es bald regnen.'::text,'wird'::text,'wird'::text,NULL::text,'Graue Wolken sind nasse Wolken, also wird es bald regnen.'::text),
(311524,34614,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сірі хмари — це мокрі хмари, тож скоро ...'::text,'збирається на дощ'::text,'піде дощ'::text,NULL::text,'Сірі хмари — це мокрі хмари, тож скоро збирається на дощ.'::text),
(311523,34614,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las nubes grises son nubes mojadas, así que pronto ...'::text,'va a llover'::text,'lloverá'::text,NULL::text,'Las nubes grises son nubes mojadas, así que pronto va a llover.'::text),
(311522,34614,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les nuages gris sont des nuages mouillés, donc il ... bientôt.'::text,'va pleuvoir'::text,'pleuvra'::text,NULL::text,'Les nuages gris sont des nuages mouillés, donc il va pleuvoir bientôt.'::text),
(311525,34614,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gri bulutlar ıslak bulutlardır, bu yüzden yakında yağmur ...'::text,'yağacak'::text,'yağacak'::text,NULL::text,'Gri bulutlar ıslak bulutlardır, bu yüzden yakında yağmur yağacak.'::text),
(311526,34614,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szürke felhők vizes felhők, szóval hamarosan ... az eső.'::text,'esni fog'::text,'esni fog'::text,NULL::text,'A szürke felhők vizes felhők, szóval hamarosan esni fog az eső.'::text),
(311529,34615,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Es regnet! Sie sagt: Ich ... für immer im Regen tanzen!'::text,'muss'::text,'muss'::text,'muss nicht'::text,'Es regnet! Sie sagt: Ich muss für immer im Regen tanzen!'::text),
(311533,34615,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дощ! Вона каже: я ... танцювати під дощем вічно!'::text,'мушу'::text,'маю'::text,'не мушу'::text,'Дощ! Вона каже: я мушу танцювати під дощем вічно!'::text),
(311532,34615,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Llueve! Ella dice: ¡... bailar bajo la lluvia para siempre!'::text,'Debo'::text,'Tengo que'::text,'No tengo que'::text,'¡Llueve! Ella dice: ¡Debo bailar bajo la lluvia para siempre!'::text),
(311531,34615,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il pleut ! Elle dit : je ... danser sous la pluie pour toujours !'::text,'dois'::text,'dois'::text,'n''ai pas à'::text,'Il pleut ! Elle dit : je dois danser sous la pluie pour toujours !'::text),
(311534,34615,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yağmur yağıyor! Diyor ki: Sonsuza kadar yağmurda ...!'::text,'dans etmeliyim'::text,'dans etmek zorundayım'::text,'dans etmek zorunda değilim'::text,'Yağmur yağıyor! Diyor ki: Sonsuza kadar yağmurda dans etmeliyim!'::text),
(311535,34615,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esik! Azt mondja: örökké ... táncolnom az esőben!'::text,'kell'::text,'kell'::text,'nem kell'::text,'Esik! Azt mondja: örökké kell táncolnom az esőben!'::text),
(311538,34616,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Es regnet! Sie ... reingehen, bevor die Katastrophe kommt!'::text,'sollte'::text,'sollte'::text,'soll'::text,'Es regnet! Sie sollte reingehen, bevor die Katastrophe kommt!'::text),
(311542,34616,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Іде дощ! Вона ... зайти всередину, поки не сталася біда!'::text,'мала б'::text,'мала б'::text,'буде'::text,'Іде дощ! Вона мала б зайти всередину, поки не сталася біда!'::text),
(311541,34616,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Está lloviendo! ¡... entrar antes de que llegue el desastre!'::text,'Debería'::text,'Debería'::text,'Deberá'::text,'¡Está lloviendo! ¡Debería entrar antes de que llegue el desastre!'::text),
(311540,34616,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il pleut ! Elle ... rentrer avant que la catastrophe arrive !'::text,'devrait'::text,'devrait'::text,'devra'::text,'Il pleut ! Elle devrait rentrer avant que la catastrophe arrive !'::text),
(311543,34616,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yağmur yağıyor! Felaket gelmeden içeri ...!'::text,'girmeli'::text,'girmeli'::text,'girecek'::text,'Yağmur yağıyor! Felaket gelmeden içeri girmeli!'::text),
(311544,34616,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esik az eső! Be ... mennie, mielőtt lecsap a katasztrófa!'::text,'kellene'::text,'kellene'::text,'kell'::text,'Esik az eső! Be kellene mennie, mielőtt lecsap a katasztrófa!'::text),
(324957,36107,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frettchen ... ein langes graues Rohr.'::text,'haben'::text,'hat'::text,'haben'::text,'Die Frettchen haben ein langes graues Rohr.'::text),
(324961,36107,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тхори ... довгу сіру трубу.'::text,'мають'::text,'має'::text,'мають'::text,'Тхори мають довгу сіру трубу.'::text),
(324960,36107,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los hurones ... un tubo largo y gris.'::text,'tienen'::text,'tiene'::text,'tienen'::text,'Los hurones tienen un tubo largo y gris.'::text),
(324959,36107,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les furets ... un long tube gris.'::text,'ont'::text,'a'::text,'ont'::text,'Les furets ont un long tube gris.'::text),
(324962,36107,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gelinciklerin uzun gri bir borusu ...'::text,'var'::text,'var'::text,'var'::text,'Gelinciklerin uzun gri bir borusu var.'::text),
(324963,36107,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A görényeknek ... egy hosszú szürke csövük.'::text,'van'::text,'van'::text,'van'::text,'A görényeknek van egy hosszú szürke csövük.'::text),
(324966,36108,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein Frettchen ... in ein Ende des Rohrs.'::text,'rennt'::text,'rennen'::text,'rennend'::text,'Ein Frettchen rennt in ein Ende des Rohrs.'::text),
(324970,36108,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тхір ... в один кінець труби.'::text,'забігає'::text,'забігати'::text,'забігаючи'::text,'Тхір забігає в один кінець труби.'::text),
(324969,36108,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un hurón ... hacia un extremo del tubo.'::text,'corre'::text,'correr'::text,'corriendo'::text,'Un hurón corre hacia un extremo del tubo.'::text),
(324968,36108,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un furet ... dans un bout du tube.'::text,'court'::text,'courir'::text,'courant'::text,'Un furet court dans un bout du tube.'::text),
(324971,36108,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir gelincik borunun bir ucuna ...'::text,'koşar'::text,'koşmak'::text,'koşarak'::text,'Bir gelincik borunun bir ucuna koşar.'::text),
(324972,36108,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy görény ... a cső egyik végébe.'::text,'fut'::text,'futni'::text,'futó'::text,'Egy görény fut a cső egyik végébe.'::text),
(324975,36109,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Rohr ist leer, also ... ein Frettchen hindurchrennen.'::text,'kann'::text,'kann'::text,'ist'::text,'Das Rohr ist leer, also kann ein Frettchen hindurchrennen.'::text),
(324979,36109,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Труба порожня, тож тхір ... пробігти крізь неї.'::text,'може'::text,'може'::text,'є'::text,'Труба порожня, тож тхір може пробігти крізь неї.'::text),
(324978,36109,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El tubo está vacío, así que un hurón ... atravesarlo corriendo.'::text,'puede'::text,'puede'::text,'está'::text,'El tubo está vacío, así que un hurón puede atravesarlo corriendo.'::text),
(324977,36109,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le tube est vide, donc un furet ... le traverser en courant.'::text,'peut'::text,'peut'::text,'est'::text,'Le tube est vide, donc un furet peut le traverser en courant.'::text),
(324980,36109,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Boru boş, bu yüzden bir gelincik içinden ...'::text,'koşabilir'::text,'koşabilir'::text,NULL::text,'Boru boş, bu yüzden bir gelincik içinden koşabilir.'::text),
(324981,36109,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A cső üres, így egy görény ... rajta.'::text,'átfuthat'::text,'átfuthat'::text,'van'::text,'A cső üres, így egy görény átfuthat rajta.'::text),
(325002,36112,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sehr ordentlich, klar: so ... Füllflocken auf dem Boden neben dem Rohr.'::text,'viele'::text,'viel'::text,'irgendwelche'::text,'Sehr ordentlich, klar: so viele Füllflocken auf dem Boden neben dem Rohr.'::text),
(325006,36112,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дуже охайно, авжеж: так ... пінопластових кульок на підлозі біля труби.'::text,'багато'::text,'багато'::text,'будь-яких'::text,'Дуже охайно, авжеж: так багато пінопластових кульок на підлозі біля труби.'::text),
(325005,36112,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Muy ordenado, claro: vaya, hay ... bolitas de relleno en el suelo junto al tubo.'::text,'muchas'::text,'mucha'::text,'cualquier'::text,'Muy ordenado, claro: vaya, hay muchas bolitas de relleno en el suelo junto al tubo.'::text),
(325004,36112,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Très rangé, évidemment : il y a ... billes de calage par terre près du tube.'::text,'beaucoup de'::text,'beaucoup de'::text,'n''importe quelles'::text,'Très rangé, évidemment : il y a beaucoup de billes de calage par terre près du tube.'::text),
(325007,36112,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çok düzenli, belli ki: borunun yanında yerde o kadar ... strafor parçası var.'::text,'çok'::text,'çok'::text,'herhangi'::text,'Çok düzenli, belli ki: borunun yanında yerde o kadar çok strafor parçası var.'::text),
(325008,36112,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nagyon rendes, nyilván: jó ... habgolyó van a padlón a cső mellett.'::text,'sok'::text,'sok'::text,'bármilyen'::text,'Nagyon rendes, nyilván: jó sok habgolyó van a padlón a cső mellett.'::text),
(325011,36113,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super gemacht, klar: Da ... rosa Füllflocken überall auf dem Rohr.'::text,'sind'::text,'ist'::text,'sein'::text,'Super gemacht, klar: Da sind rosa Füllflocken überall auf dem Rohr.'::text),
(325015,36113,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудова робота, авжеж: по всій трубі ... рожеві пінопластові кульки.'::text,'є'::text,'є'::text,'бути'::text,'Чудова робота, авжеж: по всій трубі є рожеві пінопластові кульки.'::text),
(325014,36113,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buen trabajo, claro: ... bolitas rosas por todo el tubo.'::text,'hay'::text,'hay'::text,'hay'::text,'Buen trabajo, claro: hay bolitas rosas por todo el tubo.'::text),
(325013,36113,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beau travail, évidemment : ... des billes roses partout sur le tube.'::text,'il y a'::text,'il y a'::text,'il y a'::text,'Beau travail, évidemment : il y a des billes roses partout sur le tube.'::text),
(325016,36113,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika iş, belli ki: borunun her yerinde pembe strafor parçaları ...'::text,'var'::text,'var'::text,'olmak'::text,'Harika iş, belli ki: borunun her yerinde pembe strafor parçaları var.'::text),
(325017,36113,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szép munka, nyilván: az egész csövön rózsaszín habgolyók ...'::text,'vannak'::text,'van'::text,'lenni'::text,'Szép munka, nyilván: az egész csövön rózsaszín habgolyók vannak.'::text),
(325020,36114,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, es taucht ins Rohr ... ploppt am Ende wieder raus, legendär.'::text,'und'::text,'aber'::text,'weil'::text,'Alter, es taucht ins Rohr und ploppt am Ende wieder raus, legendär.'::text),
(325024,36114,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він пірнає в трубу ... вискакує з кінця, легенда.'::text,'і'::text,'але'::text,'бо'::text,'Бро, він пірнає в трубу і вискакує з кінця, легенда.'::text),
(325023,36114,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, se mete en el tubo ... sale disparado por el otro extremo, icónico.'::text,'y'::text,'pero'::text,'porque'::text,'Tío, se mete en el tubo y sale disparado por el otro extremo, icónico.'::text),
(325022,36114,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, il plonge dans le tube ... ressort au bout, iconique.'::text,'et'::text,'mais'::text,'parce qu''il'::text,'Frère, il plonge dans le tube et ressort au bout, iconique.'::text),
(325025,36114,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, boruya dalıyor ... ucundan fırlıyor, efsane.'::text,'ve'::text,'ama'::text,'çünkü'::text,'Kanka, boruya dalıyor ve ucundan fırlıyor, efsane.'::text),
(325026,36114,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, beugrik a csőbe, ... a végén kipattan, ikonikus.'::text,'és'::text,'de'::text,'mert'::text,'Tesó, beugrik a csőbe, és a végén kipattan, ikonikus.'::text),
(300720,33414,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sehr unauffällig, klar: Gestern Abend ... er mit einem riesigen Schild davon.'::text,'eilte'::text,'eilt'::text,'eilte'::text,'Sehr unauffällig, klar: Gestern Abend eilte er mit einem riesigen Schild davon.'::text),
(300724,33414,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дуже непомітно, авжеж: учора ввечері він ... геть з величезною вивіскою.'::text,'помчав'::text,'мчить'::text,'помчав'::text,'Дуже непомітно, авжеж: учора ввечері він помчав геть з величезною вивіскою.'::text),
(300723,33414,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Muy discreto, claro: anoche ... con un cartel enorme.'::text,'se fue corriendo'::text,'se va corriendo'::text,'se fue corriendo'::text,'Muy discreto, claro: anoche se fue corriendo con un cartel enorme.'::text),
(300722,33414,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Très discret, évidemment : hier soir, il ... avec un énorme panneau.'::text,'a filé'::text,'file'::text,'a filé'::text,'Très discret, évidemment : hier soir, il a filé avec un énorme panneau.'::text),
(300725,33414,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hiç dikkat çekmeden, tabii: dün gece koca bir tabelayla aceleyle ...'::text,'uzaklaştı'::text,'uzaklaşır'::text,'uzaklaştı'::text,'Hiç dikkat çekmeden, tabii: dün gece koca bir tabelayla aceleyle uzaklaştı.'::text),
(300726,33414,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nagyon feltűnésmentes, nyilván: tegnap este egy hatalmas táblával ... el.'::text,'sietett'::text,'siet'::text,'sietett'::text,'Nagyon feltűnésmentes, nyilván: tegnap este egy hatalmas táblával sietett el.'::text),
(300729,33415,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalerweise geht er zu Fuß, aber gestern Abend ... er mit dem geklauten Schild! Chaos!'::text,'eilte'::text,'eilt'::text,NULL::text,'Normalerweise geht er zu Fuß, aber gestern Abend eilte er mit dem geklauten Schild! Chaos!'::text),
(300733,33415,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай він ходить пішки, але вчора ввечері він ... з украденою вивіскою! Хаос!'::text,'мчав'::text,'мчить'::text,NULL::text,'Зазвичай він ходить пішки, але вчора ввечері він мчав з украденою вивіскою! Хаос!'::text),
(300732,33415,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente va andando, ¡pero anoche ... con el cartel robado! ¡Caos!'::text,'fue a toda prisa'::text,'va a toda prisa'::text,NULL::text,'Normalmente va andando, ¡pero anoche fue a toda prisa con el cartel robado! ¡Caos!'::text),
(300731,33415,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude il marche, mais hier soir il ... avec le panneau volé ! Chaos !'::text,'s''est dépêché'::text,'se dépêche'::text,NULL::text,'D''habitude il marche, mais hier soir il s''est dépêché avec le panneau volé ! Chaos !'::text),
(300734,33415,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde yürür ama dün gece çalıntı tabelayla ...! Kaos!'::text,'acele etti'::text,'acele eder'::text,NULL::text,'Genelde yürür ama dün gece çalıntı tabelayla acele etti! Kaos!'::text),
(300735,33415,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában sétál, de tegnap este ... a lopott táblával! Káosz!'::text,'sietett'::text,'siet'::text,NULL::text,'Általában sétál, de tegnap este sietett a lopott táblával! Káosz!'::text),
(300738,33416,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los, los, los! Er ... zum Auto! Totales Chaos!'::text,'eilt'::text,'eilt'::text,'eilt'::text,'Los, los, los! Er eilt zum Auto! Totales Chaos!'::text),
(300742,33416,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Давай, давай, давай! Він ... до машини! Повний хаос!'::text,'мчить'::text,'мчить'::text,'мчить'::text,'Давай, давай, давай! Він мчить до машини! Повний хаос!'::text),
(300741,33416,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Vamos, vamos, vamos! ¡... hacia el coche! ¡Caos total!'::text,'Está corriendo'::text,'Corre'::text,'Está corriendo'::text,'¡Vamos, vamos, vamos! ¡Está corriendo hacia el coche! ¡Caos total!'::text),
(300740,33416,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Allez, allez, allez ! Il ... vers la voiture ! Chaos total !'::text,'est en train de se dépêcher'::text,'se dépêche'::text,'est en train de se dépêcher'::text,'Allez, allez, allez ! Il est en train de se dépêcher vers la voiture ! Chaos total !'::text),
(300743,33416,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hadi, hadi, hadi! Arabaya ...! Tam bir kaos!'::text,'koşturuyor'::text,'koşturur'::text,'koşturuyor'::text,'Hadi, hadi, hadi! Arabaya koşturuyor! Tam bir kaos!'::text),
(300744,33416,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gyerünk, gyerünk, gyerünk! ... az autóhoz! Totális káosz!'::text,'Siet'::text,'Siet'::text,'Siet'::text,'Gyerünk, gyerünk, gyerünk! Siet az autóhoz! Totális káosz!'::text),
(300747,33417,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, er rennt nie, aber jetzt ... er angeblich mit einem Riesenschild.'::text,'eilt'::text,'eilt'::text,NULL::text,'Mädel, er rennt nie, aber jetzt eilt er angeblich mit einem Riesenschild.'::text),
(300751,33417,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він ніколи не бігає, але зараз, кажуть, ... з величезною вивіскою.'::text,'мчить'::text,'мчить'::text,NULL::text,'Подруго, він ніколи не бігає, але зараз, кажуть, мчить з величезною вивіскою.'::text),
(300750,33417,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, él nunca corre, pero parece que ahora ... con un cartel gigante.'::text,'está yendo a toda prisa'::text,'va a toda prisa'::text,NULL::text,'Tía, él nunca corre, pero parece que ahora está yendo a toda prisa con un cartel gigante.'::text),
(300749,33417,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, il ne court jamais, mais apparemment là il ... avec un panneau géant.'::text,'est en train de se dépêcher'::text,'se dépêche'::text,NULL::text,'Ma belle, il ne court jamais, mais apparemment là il est en train de se dépêcher avec un panneau géant.'::text),
(300752,33417,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, o hiç koşmaz ama duyduğuma göre şimdi dev bir tabelayla ...'::text,'acele ediyor'::text,'acele eder'::text,NULL::text,'Kızım, o hiç koşmaz ama duyduğuma göre şimdi dev bir tabelayla acele ediyor.'::text),
(300753,33417,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, ő sosem fut, de most állítólag ... egy óriási táblával.'::text,'siet'::text,'siet'::text,NULL::text,'Csajszi, ő sosem fut, de most állítólag siet egy óriási táblával.'::text),
(300765,33419,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hat einen Plan. Er ... zum Schild und zurück eilen.'::text,'wird'::text,'werden'::text,'wird'::text,'Er hat einen Plan. Er wird zum Schild und zurück eilen.'::text),
(300769,33419,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У нього є план. Він ... до вивіски й назад.'::text,'збирається помчати'::text,'збираються помчати'::text,'збирається помчати'::text,'У нього є план. Він збирається помчати до вивіски й назад.'::text),
(300768,33419,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tiene un plan. ... hasta el cartel y de vuelta.'::text,'Va a ir corriendo'::text,'Van a ir corriendo'::text,'Va a ir corriendo'::text,'Tiene un plan. Va a ir corriendo hasta el cartel y de vuelta.'::text),
(300767,33419,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a un plan. Il ... jusqu''au panneau et retour.'::text,'va foncer'::text,'vont foncer'::text,'va foncer'::text,'Il a un plan. Il va foncer jusqu''au panneau et retour.'::text),
(300770,33419,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir planı var. Tabelaya gidip geri ...'::text,'koşturacak'::text,'koşturacaklar'::text,'koşturacak'::text,'Bir planı var. Tabelaya gidip geri koşturacak.'::text),
(300771,33419,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Van egy terve. El ... sietni a tábláig és vissza.'::text,'fog'::text,'fognak'::text,'fog'::text,'Van egy terve. El fog sietni a tábláig és vissza.'::text),
(300774,33420,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'So ruhig, klar: Er rennt schon, also ... er davoneilen.'::text,'wird'::text,'wird'::text,NULL::text,'So ruhig, klar: Er rennt schon, also wird er davoneilen.'::text),
(300778,33420,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Такий спокійний, авжеж: він уже біжить, тож він ... втекти.'::text,'збирається'::text,'буде'::text,NULL::text,'Такий спокійний, авжеж: він уже біжить, тож він збирається втекти.'::text),
(300777,33420,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué tranquilo, claro: ya está corriendo, así que ... irse a toda prisa.'::text,'va a'::text,NULL::text,NULL::text,'Qué tranquilo, claro: ya está corriendo, así que va a irse a toda prisa.'::text),
(300776,33420,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tellement calme, évidemment : il court déjà, donc il ... filer.'::text,'va'::text,NULL::text,NULL::text,'Tellement calme, évidemment : il court déjà, donc il va filer.'::text),
(300779,33420,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çok sakin, belli ki: zaten koşuyor, bu yüzden aceleyle ...'::text,'uzaklaşacak'::text,'uzaklaşacak'::text,NULL::text,'Çok sakin, belli ki: zaten koşuyor, bu yüzden aceleyle uzaklaşacak.'::text),
(300780,33420,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Milyen nyugodt, nyilván: már fut, szóval el ... sietni.'::text,'fog'::text,'fog'::text,NULL::text,'Milyen nyugodt, nyilván: már fut, szóval el fog sietni.'::text),
(299892,33322,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... fahren auf der Autobahn, weil eine Autobahn für Autos ist.'::text,'2 Autos'::text,'2 Auto'::text,'2 Autos'::text,'2 Autos fahren auf der Autobahn, weil eine Autobahn für Autos ist.'::text),
(299896,33322,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... їдуть автомагістраллю, бо автомагістраль для машин.'::text,'2 машини'::text,'2 машина'::text,'2 машини'::text,'2 машини їдуть автомагістраллю, бо автомагістраль для машин.'::text),
(299895,33322,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... van por la autopista porque una autopista es para coches.'::text,'2 coches'::text,'2 coche'::text,'2 coches'::text,'2 coches van por la autopista porque una autopista es para coches.'::text),
(299894,33322,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... roulent sur l''autoroute parce qu''une autoroute, c''est pour les voitures.'::text,'2 voitures'::text,'2 voiture'::text,'2 voitures'::text,'2 voitures roulent sur l''autoroute parce qu''une autoroute, c''est pour les voitures.'::text),
(299897,33322,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... otoyolda gidiyor çünkü otoyol arabalar içindir.'::text,'2 araba'::text,'2 araba'::text,'2 arabalar'::text,'2 araba otoyolda gidiyor çünkü otoyol arabalar içindir.'::text),
(299898,33322,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... megy az autópályán, mert az autópálya autóknak való.'::text,'2 autó'::text,'2 autó'::text,'2 autó'::text,'2 autó megy az autópályán, mert az autópálya autóknak való.'::text),
(299901,33323,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das blaue Auto hat ... eigene Spur, weil die Autobahn Spuren hat.'::text,'seine'::text,'es ist'::text,'seine'::text,'Das blaue Auto hat seine eigene Spur, weil die Autobahn Spuren hat.'::text),
(299905,33323,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Синя машина має ... власну смугу, бо на автомагістралі є смуги.'::text,'свою'::text,'є'::text,'свою'::text,'Синя машина має свою власну смугу, бо на автомагістралі є смуги.'::text),
(299904,33323,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El coche azul tiene ... propio carril porque la autopista tiene carriles.'::text,'su'::text,'es'::text,'su'::text,'El coche azul tiene su propio carril porque la autopista tiene carriles.'::text),
(299903,33323,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La voiture bleue a ... propre voie parce que l''autoroute a des voies.'::text,'sa'::text,'c''est'::text,'sa'::text,'La voiture bleue a sa propre voie parce que l''autoroute a des voies.'::text),
(299906,33323,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mavi arabanın ... kendi şeridi var çünkü otoyolda şeritler var.'::text,'onun'::text,NULL::text,'onun'::text,'Mavi arabanın onun kendi şeridi var çünkü otoyolda şeritler var.'::text),
(299907,33323,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kék autónak megvan a saját ..., mert az autópályán sávok vannak.'::text,'sávja'::text,NULL::text,'sávja'::text,'A kék autónak megvan a saját sávja, mert az autópályán sávok vannak.'::text),
(299910,33324,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Horror! Die Berge sind direkt ... Ende der Autobahn!'::text,'am'::text,'auf dem'::text,'zum'::text,'Horror! Die Berge sind direkt am Ende der Autobahn!'::text),
(299914,33324,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жах! Гори просто ... кінці автомагістралі!'::text,'в'::text,'на'::text,'до'::text,'Жах! Гори просто в кінці автомагістралі!'::text),
(299913,33324,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Qué miedo! ¡Las montañas están justo ... final de la autopista!'::text,'al'::text,'sobre el'::text,'hacia el'::text,'¡Qué miedo! ¡Las montañas están justo al final de la autopista!'::text),
(299912,33324,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Terrifiant ! Les montagnes sont juste ... bout de l''autoroute !'::text,'au'::text,'sur le'::text,'vers le'::text,'Terrifiant ! Les montagnes sont juste au bout de l''autoroute !'::text),
(299915,33324,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Korkunç! Dağlar tam otoyolun ...!'::text,'sonunda'::text,'üstünde'::text,'sonuna'::text,'Korkunç! Dağlar tam otoyolun sonunda!'::text),
(299916,33324,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rémisztő! A hegyek pont az autópálya ...!'::text,'végén'::text,'végén'::text,'végéhez'::text,'Rémisztő! A hegyek pont az autópálya végén!'::text),
(299919,33325,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Autobahn ist ... hundert Kilometer lang! Nie wieder!'::text,'zwei'::text,'zweite'::text,'Zweien'::text,'Die Autobahn ist zwei hundert Kilometer lang! Nie wieder!'::text),
(299923,33325,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Автомагістраль завдовжки ... сотні кілометрів! Ніколи більше!'::text,'дві'::text,'друга'::text,'двійки'::text,'Автомагістраль завдовжки дві сотні кілометрів! Ніколи більше!'::text),
(299922,33325,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La autopista tiene ... centenares de kilómetros! ¡Nunca más!'::text,'dos'::text,'segundo'::text,'dos'::text,'¡La autopista tiene dos centenares de kilómetros! ¡Nunca más!'::text),
(299921,33325,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''autoroute fait ... cents kilomètres de long ! Plus jamais !'::text,'deux'::text,'deuxième'::text,'deux'::text,'L''autoroute fait deux cents kilomètres de long ! Plus jamais !'::text),
(299924,33325,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Otoyol ... yüz kilometre uzunluğunda! Bir daha asla!'::text,'iki'::text,'ikinci'::text,'ikiler'::text,'Otoyol iki yüz kilometre uzunluğunda! Bir daha asla!'::text),
(299925,33325,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az autópálya ... száz kilométer hosszú! Soha többé!'::text,'két'::text,'második'::text,'kettesek'::text,'Az autópálya két száz kilométer hosszú! Soha többé!'::text),
(299937,33327,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine volle Autobahn, klar: Da sind nur ... Autos drauf.'::text,'ein paar'::text,'ein bisschen'::text,'viel'::text,'Eine volle Autobahn, klar: Da sind nur ein paar Autos drauf.'::text),
(299941,33327,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жвава автомагістраль, авжеж: на ній лише ... машин.'::text,'кілька'::text,'трохи'::text,'багато'::text,'Жвава автомагістраль, авжеж: на ній лише кілька машин.'::text),
(299940,33327,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una autopista con mucho tráfico, claro: solo hay ... coches.'::text,'unos pocos'::text,'un poco de'::text,'mucho'::text,'Una autopista con mucho tráfico, claro: solo hay unos pocos coches.'::text),
(299939,33327,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une autoroute chargée, évidemment : il n''y a que ... voitures dessus.'::text,'quelques'::text,'un peu de'::text,'beaucoup de'::text,'Une autoroute chargée, évidemment : il n''y a que quelques voitures dessus.'::text),
(299942,33327,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yoğun bir otoyol, belli ki: üstünde sadece ... araba var.'::text,'birkaç'::text,'biraz'::text,'çok'::text,'Yoğun bir otoyol, belli ki: üstünde sadece birkaç araba var.'::text),
(299943,33327,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Forgalmas autópálya, nyilván: csak ... autó van rajta.'::text,'pár'::text,'egy kis'::text,'sok'::text,'Forgalmas autópálya, nyilván: csak pár autó van rajta.'::text),
(299946,33328,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Am Ende der Autobahn ... Berge.'::text,'sind'::text,'ist'::text,'sein'::text,'Am Ende der Autobahn sind Berge.'::text),
(299950,33328,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У кінці автомагістралі ... гори.'::text,'є'::text,'є'::text,'бути'::text,'У кінці автомагістралі є гори.'::text),
(299949,33328,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... montañas al final de la autopista.'::text,'Hay'::text,'Hay'::text,'Hay'::text,'Hay montañas al final de la autopista.'::text),
(299948,33328,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... des montagnes au bout de l''autoroute.'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Il y a des montagnes au bout de l''autoroute.'::text),
(299951,33328,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Otoyolun sonunda dağlar ...'::text,'var'::text,'var'::text,'olmak'::text,'Otoyolun sonunda dağlar var.'::text),
(299952,33328,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az autópálya végén hegyek ...'::text,'vannak'::text,'van'::text,'lenni'::text,'Az autópálya végén hegyek vannak.'::text),
(318801,35423,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee Alter, Tennis ist ... cooler Sport, probier ich aus.'::text,'ein'::text,'der'::text,'ein'::text,'Nee Alter, Tennis ist ein cooler Sport, probier ich aus.'::text),
(318805,35423,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, бро, теніс — це ... крутий спорт, спробую.'::text,''::text,NULL::text,NULL::text,'Не, бро, теніс — це крутий спорт, спробую.'::text),
(318804,35423,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, tío, el tenis es ... deporte guay, lo voy a probar.'::text,'un'::text,'el'::text,'un'::text,'Qué va, tío, el tenis es un deporte guay, lo voy a probar.'::text),
(318803,35423,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan frère, le tennis c''est ... sport cool, je vais essayer.'::text,'un'::text,'le'::text,'un'::text,'Nan frère, le tennis c''est un sport cool, je vais essayer.'::text),
(318806,35423,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, tenis ... havalı spor, deneyeceğim.'::text,'bir'::text,NULL::text,'bir'::text,'Yok kanka, tenis bir havalı spor, deneyeceğim.'::text),
(318807,35423,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem, tesó, a tenisz ... menő sport, kipróbálom.'::text,'egy'::text,'a'::text,'egy'::text,'Nem, tesó, a tenisz egy menő sport, kipróbálom.'::text),
(318810,35424,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, ... Sport ist so schwer, ich muss üben.'::text,'dieser'::text,'diese'::text,'jene'::text,'Alter, dieser Sport ist so schwer, ich muss üben.'::text),
(318814,35424,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ... спорт такий важкий, треба тренуватися.'::text,'цей'::text,'ці'::text,'ті'::text,'Бро, цей спорт такий важкий, треба тренуватися.'::text),
(318813,35424,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ... deporte es muy difícil, tengo que entrenar.'::text,'este'::text,'estos'::text,'esos'::text,'Tío, este deporte es muy difícil, tengo que entrenar.'::text),
(318812,35424,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, ... sport est trop dur, faut que je m''entraîne.'::text,'ce'::text,'ces'::text,'ces'::text,'Frère, ce sport est trop dur, faut que je m''entraîne.'::text),
(318815,35424,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, ... spor çok zor, antrenman yapmam lazım.'::text,'bu'::text,'bu'::text,'şu'::text,'Kanka, bu spor çok zor, antrenman yapmam lazım.'::text),
(318816,35424,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ... a sport nagyon nehéz, gyakorolnom kell.'::text,'ez'::text,'ezek'::text,'azok'::text,'Tesó, ez a sport nagyon nehéz, gyakorolnom kell.'::text),
(318819,35425,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ziel: Sie spielt ... Sport 5 Abende pro Woche.'::text,'ihren'::text,'seinen'::text,'seinen'::text,'Ziel: Sie spielt ihren Sport 5 Abende pro Woche.'::text),
(318823,35425,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ціль: вона займається ... спортом 5 вечорів на тиждень.'::text,'своїм'::text,'своїм'::text,'своїм'::text,'Ціль: вона займається своїм спортом 5 вечорів на тиждень.'::text),
(318822,35425,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Objetivo: practica ... deporte 5 noches a la semana.'::text,'su'::text,'su'::text,'su'::text,'Objetivo: practica su deporte 5 noches a la semana.'::text),
(318821,35425,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Objectif : elle pratique ... sport 5 soirs par semaine.'::text,'son'::text,'son'::text,'son'::text,'Objectif : elle pratique son sport 5 soirs par semaine.'::text),
(318824,35425,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hedef: ... sporunu haftada 5 akşam yapıyor.'::text,'onun'::text,'onun'::text,'onun'::text,'Hedef: onun sporunu haftada 5 akşam yapıyor.'::text),
(318825,35425,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cél: heti 5 este űzi a ...'::text,'sportját'::text,'sportját'::text,'sportját'::text,'Cél: heti 5 este űzi a sportját.'::text),
(318828,35426,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... macht sie Sport? Weil der Platz da ist.'::text,'Warum'::text,'Wer'::text,'Wo'::text,'Warum macht sie Sport? Weil der Platz da ist.'::text),
(318832,35426,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... вона займається спортом? Бо корт тут.'::text,'Чому'::text,'Хто'::text,'Де'::text,'Чому вона займається спортом? Бо корт тут.'::text),
(318831,35426,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... hace deporte? Porque la pista está ahí.'::text,'Por qué'::text,'Quién'::text,'Dónde'::text,'¿Por qué hace deporte? Porque la pista está ahí.'::text),
(318830,35426,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... fait-elle du sport ? Parce que le court est là.'::text,'Pourquoi'::text,'Qui'::text,'Où'::text,'Pourquoi fait-elle du sport ? Parce que le court est là.'::text),
(318833,35426,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... spor yapıyor? Çünkü kort orada.'::text,'Neden'::text,'Kim'::text,'Nerede'::text,'Neden spor yapıyor? Çünkü kort orada.'::text),
(318834,35426,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... sportol? Mert ott van a pálya.'::text,'Miért'::text,'Ki'::text,'Hol'::text,'Miért sportol? Mert ott van a pálya.'::text),
(318846,35428,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Albtraum! Sie spielt diesen Sport ... Stunden lang!'::text,'drei'::text,'dritte'::text,'dreimal'::text,'Albtraum! Sie spielt diesen Sport drei Stunden lang!'::text),
(318850,35428,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жах! Вона займається цим спортом ... години!'::text,'три'::text,'третю'::text,'тричі'::text,'Жах! Вона займається цим спортом три години!'::text),
(318849,35428,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Pesadilla! ¡Practica este deporte durante ... horas!'::text,'tres'::text,'tercera'::text,'tres veces'::text,'¡Pesadilla! ¡Practica este deporte durante tres horas!'::text),
(318848,35428,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cauchemar ! Elle pratique ce sport pendant ... heures !'::text,'trois'::text,'troisième'::text,'trois fois'::text,'Cauchemar ! Elle pratique ce sport pendant trois heures !'::text),
(318851,35428,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâbus! Bu sporu ... saat boyunca oynuyor!'::text,'üç'::text,'üçüncü'::text,'üç kez'::text,'Kâbus! Bu sporu üç saat boyunca oynuyor!'::text),
(318852,35428,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rémálom! ... órán át űzi ezt a sportot!'::text,'Három'::text,'Harmadik'::text,'Háromszor'::text,'Rémálom! Három órán át űzi ezt a sportot!'::text),
(318855,35429,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gestern Abend ... sie ihren Lieblingssport unter dem Flutlicht.'::text,'spielte'::text,'spielt'::text,'spielen'::text,'Gestern Abend spielte sie ihren Lieblingssport unter dem Flutlicht.'::text),
(318859,35429,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учора ввечері вона ... своїм улюбленим спортом під прожекторами.'::text,'займалася'::text,'займається'::text,'займатися'::text,'Учора ввечері вона займалася своїм улюбленим спортом під прожекторами.'::text),
(318858,35429,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Anoche ... su deporte favorito bajo los focos.'::text,'practicó'::text,'practica'::text,'practicar'::text,'Anoche practicó su deporte favorito bajo los focos.'::text),
(318857,35429,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier soir, elle ... son sport préféré sous les projecteurs.'::text,'a pratiqué'::text,'pratique'::text,'pratiquer'::text,'Hier soir, elle a pratiqué son sport préféré sous les projecteurs.'::text),
(318860,35429,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün akşam en sevdiği sporu ışıklar altında ...'::text,'yaptı'::text,'yapar'::text,'yapmak'::text,'Dün akşam en sevdiği sporu ışıklar altında yaptı.'::text),
(318861,35429,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap este a reflektorok alatt ... a kedvenc sportját.'::text,'űzte'::text,'űzi'::text,'űzni'::text,'Tegnap este a reflektorok alatt űzte a kedvenc sportját.'::text),
(299802,33312,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meine Beine ... hoch über dem Tal. Das ist ein Albtraum!'::text,'sind'::text,'ist'::text,'bin'::text,'Meine Beine sind hoch über dem Tal. Das ist ein Albtraum!'::text),
(299806,33312,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Мої ноги ... високо над долиною. Це жах!'::text,'є'::text,'є'::text,'є'::text,'Мої ноги є високо над долиною. Це жах!'::text),
(299805,33312,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mis piernas ... muy por encima del valle. ¡Esto es una pesadilla!'::text,'están'::text,'está'::text,'estoy'::text,'Mis piernas están muy por encima del valle. ¡Esto es una pesadilla!'::text),
(299804,33312,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mes jambes ... haut au-dessus de la vallée. C''est un cauchemar !'::text,'sont'::text,'est'::text,'suis'::text,'Mes jambes sont haut au-dessus de la vallée. C''est un cauchemar !'::text),
(299807,33312,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bacaklarım ... vadinin çok yukarısında. Bu bir kâbus!'::text,''::text,NULL::text,NULL::text,'Bacaklarım vadinin çok yukarısında. Bu bir kâbus!'::text),
(299808,33312,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lábaim ... magasan a völgy fölött. Ez egy rémálom!'::text,'vannak'::text,'van'::text,'vagyok'::text,'A lábaim vannak magasan a völgy fölött. Ez egy rémálom!'::text),
(299811,33313,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Flieger ... hoch über dem grünen Tal.'::text,'fliegt'::text,'fliegen'::text,'fliegend'::text,'Der Flieger fliegt hoch über dem grünen Tal.'::text),
(299815,33313,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пілот ... високо над зеленою долиною.'::text,'летить'::text,'летіти'::text,'летячи'::text,'Пілот летить високо над зеленою долиною.'::text),
(299814,33313,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El piloto ... muy alto sobre el valle verde.'::text,'vuela'::text,'volar'::text,'volando'::text,'El piloto vuela muy alto sobre el valle verde.'::text),
(299813,33313,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le pilote ... haut au-dessus de la vallée verte.'::text,'vole'::text,'voler'::text,'volant'::text,'Le pilote vole haut au-dessus de la vallée verte.'::text),
(299816,33313,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pilot yeşil vadinin çok üstünde ...'::text,'uçar'::text,'uçmak'::text,'uçarak'::text,'Pilot yeşil vadinin çok üstünde uçar.'::text),
(299817,33313,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A pilóta magasan a zöld völgy fölött ...'::text,'repül'::text,'repülni'::text,'repülő'::text,'A pilóta magasan a zöld völgy fölött repül.'::text),
(299838,33316,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, das ist deine eigene Regel: Du ... jeden Sommer so hoch fliegen.'::text,'musst'::text,'musst'::text,'darfst nicht'::text,'Ehrlich, das ist deine eigene Regel: Du musst jeden Sommer so hoch fliegen.'::text),
(299842,33316,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, це твоє власне правило: ти ... літати так високо щоліта.'::text,'мусиш'::text,'маєш'::text,'не смієш'::text,'Чесно, це твоє власне правило: ти мусиш літати так високо щоліта.'::text),
(299841,33316,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, es tu propia regla: ... volar así de alto cada verano.'::text,'debes'::text,'tienes que'::text,'no debes'::text,'Sinceramente, es tu propia regla: debes volar así de alto cada verano.'::text),
(299840,33316,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, c''est ta propre règle : tu ... voler aussi haut chaque été.'::text,'dois'::text,'dois'::text,'ne dois pas'::text,'Franchement, c''est ta propre règle : tu dois voler aussi haut chaque été.'::text),
(299843,33316,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, bu senin kendi kuralın: her yaz bu kadar yüksekte ...'::text,'uçmalısın'::text,'uçmak zorundasın'::text,'uçmamalısın'::text,'Açıkçası, bu senin kendi kuralın: her yaz bu kadar yüksekte uçmalısın.'::text),
(299844,33316,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ez a saját szabályod: minden nyáron ilyen magasan ... repülnöd.'::text,'kell'::text,'kell'::text,'nem szabad'::text,'Őszintén, ez a saját szabályod: minden nyáron ilyen magasan kell repülnöd.'::text),
(299847,33317,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super gemacht, so hoch in Shorts zu fliegen. Nächstes Mal ... du eine lange Hose anziehen.'::text,'solltest'::text,'solltest'::text,'solltest'::text,'Super gemacht, so hoch in Shorts zu fliegen. Nächstes Mal solltest du eine lange Hose anziehen.'::text),
(299851,33317,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудова робота — літати так високо в шортах. Наступного разу ти ... вдягнути штани.'::text,'мав би'::text,'мав би'::text,'мав би'::text,'Чудова робота — літати так високо в шортах. Наступного разу ти мав би вдягнути штани.'::text),
(299850,33317,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buen trabajo, volar tan alto en pantalones cortos. La próxima vez ... ponerte pantalones largos.'::text,'deberías'::text,'deberías'::text,'deberías'::text,'Buen trabajo, volar tan alto en pantalones cortos. La próxima vez deberías ponerte pantalones largos.'::text),
(299849,33317,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beau travail, voler aussi haut en short. La prochaine fois, tu ... mettre un pantalon.'::text,'devrais'::text,'devrais'::text,'devrais'::text,'Beau travail, voler aussi haut en short. La prochaine fois, tu devrais mettre un pantalon.'::text),
(299852,33317,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika iş, şortla bu kadar yüksekte uçmak. Bir dahaki sefere pantolon ...'::text,'giymelisin'::text,'giymelisin'::text,'giymelisin'::text,'Harika iş, şortla bu kadar yüksekte uçmak. Bir dahaki sefere pantolon giymelisin.'::text),
(299853,33317,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szép munka, ilyen magasan repülni rövidnadrágban. Legközelebb hosszúnadrágot ... felvenned.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'Szép munka, ilyen magasan repülni rövidnadrágban. Legközelebb hosszúnadrágot kellene felvenned.'::text),
(299856,33318,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hoch fliegen mit nackten Beinen und Turnschuhen: natürlich ... für die Dolomiten angezogen.'::text,'perfekt'::text,'perfekt'::text,'Perfektion'::text,'Hoch fliegen mit nackten Beinen und Turnschuhen: natürlich perfekt für die Dolomiten angezogen.'::text),
(299860,33318,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Літати високо з голими ногами й у кросівках: звісно, ... вдягнений для Доломітів.'::text,'ідеально'::text,'ідеальний'::text,'ідеальність'::text,'Літати високо з голими ногами й у кросівках: звісно, ідеально вдягнений для Доломітів.'::text),
(299859,33318,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Volar alto con las piernas al aire y zapatillas: obviamente vestido ... para los Dolomitas.'::text,'perfectamente'::text,'perfecto'::text,'perfección'::text,'Volar alto con las piernas al aire y zapatillas: obviamente vestido perfectamente para los Dolomitas.'::text),
(299858,33318,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Voler haut jambes nues et en baskets : évidemment habillé ... pour les Dolomites.'::text,'parfaitement'::text,'parfait'::text,'perfection'::text,'Voler haut jambes nues et en baskets : évidemment habillé parfaitement pour les Dolomites.'::text),
(299861,33318,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çıplak bacaklar ve spor ayakkabılarla yüksekte uçmak: belli ki Dolomitler için ... giyinmiş.'::text,'mükemmel bir şekilde'::text,'mükemmel'::text,'mükemmellik'::text,'Çıplak bacaklar ve spor ayakkabılarla yüksekte uçmak: belli ki Dolomitler için mükemmel bir şekilde giyinmiş.'::text),
(299862,33318,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Magasan repülni csupasz lábbal és sportcipőben: nyilván ... felöltözve a Dolomitokhoz.'::text,'tökéletesen'::text,'tökéletes'::text,'tökéletesség'::text,'Magasan repülni csupasz lábbal és sportcipőben: nyilván tökéletesen felöltözve a Dolomitokhoz.'::text),
(299865,33319,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tolle Idee, klar. Meine Beine sind kalt, ... wir so hoch fliegen.'::text,'weil'::text,'also'::text,'aber'::text,'Tolle Idee, klar. Meine Beine sind kalt, weil wir so hoch fliegen.'::text),
(299869,33319,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудова ідея, авжеж. Мої ноги мерзнуть, ... ми летимо так високо.'::text,'бо'::text,'тому'::text,'але'::text,'Чудова ідея, авжеж. Мої ноги мерзнуть, бо ми летимо так високо.'::text),
(299868,33319,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gran idea, claro. Tengo las piernas frías ... volamos muy alto.'::text,'porque'::text,'así que'::text,'pero'::text,'Gran idea, claro. Tengo las piernas frías porque volamos muy alto.'::text),
(299867,33319,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super idée, évidemment. J''ai les jambes gelées ... nous volons si haut.'::text,'parce que'::text,'donc'::text,'mais'::text,'Super idée, évidemment. J''ai les jambes gelées parce que nous volons si haut.'::text),
(299870,33319,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika fikir, belli ki. Bacaklarım üşüyor ... çok yüksekte uçuyoruz.'::text,'çünkü'::text,'bu yüzden'::text,'ama'::text,'Harika fikir, belli ki. Bacaklarım üşüyor çünkü çok yüksekte uçuyoruz.'::text),
(299871,33319,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Remek ötlet, nyilván. Fázik a lábam, ... ilyen magasan repülünk.'::text,'mert'::text,'ezért'::text,'de'::text,'Remek ötlet, nyilván. Fázik a lábam, mert ilyen magasan repülünk.'::text),
(295752,32862,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mechaniker arbeitet an ... Front des gelben Autos.'::text,'der'::text,'einer'::text,'einer'::text,'Der Mechaniker arbeitet an der Front des gelben Autos.'::text),
(295756,32862,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Механік працює над ... передньою частиною жовтої машини.'::text,''::text,NULL::text,NULL::text,'Механік працює над передньою частиною жовтої машини.'::text),
(295755,32862,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El mecánico trabaja en ... parte delantera del coche amarillo.'::text,'la'::text,'una'::text,'una'::text,'El mecánico trabaja en la parte delantera del coche amarillo.'::text),
(295754,32862,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le mécanicien travaille sur ... avant de la voiture jaune.'::text,'l'''::text,'un'::text,'un'::text,'Le mécanicien travaille sur l'' avant de la voiture jaune.'::text),
(295757,32862,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamirci sarı arabanın ... ön kısmında çalışıyor.'::text,''::text,'bir'::text,'bir'::text,'Tamirci sarı arabanın ön kısmında çalışıyor.'::text),
(295758,32862,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szerelő ... sárga autó elején dolgozik.'::text,'a'::text,'egy'::text,'egy'::text,'A szerelő a sárga autó elején dolgozik.'::text),
(295770,32864,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mechaniker beugt sich über das gelbe Auto und repariert ... Front.'::text,'seine'::text,'seine'::text,'ihre'::text,'Der Mechaniker beugt sich über das gelbe Auto und repariert seine Front.'::text),
(295774,32864,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Механік схиляється над жовтою машиною й лагодить ... передню частину.'::text,'її'::text,'його'::text,'їхню'::text,'Механік схиляється над жовтою машиною й лагодить її передню частину.'::text),
(295773,32864,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El mecánico se inclina sobre el coche amarillo y arregla ... parte delantera.'::text,'su'::text,'su'::text,'su'::text,'El mecánico se inclina sobre el coche amarillo y arregla su parte delantera.'::text),
(295772,32864,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le mécanicien se penche sur la voiture jaune et répare ... avant.'::text,'son'::text,'son'::text,'leur'::text,'Le mécanicien se penche sur la voiture jaune et répare son avant.'::text),
(295775,32864,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamirci sarı arabanın üstüne eğiliyor ve ... ön kısmını tamir ediyor.'::text,'onun'::text,'onun'::text,'onların'::text,'Tamirci sarı arabanın üstüne eğiliyor ve onun ön kısmını tamir ediyor.'::text),
(295776,32864,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szerelő a sárga autó fölé hajol, és megjavítja az ...'::text,'elejét'::text,'elejét'::text,'elejüket'::text,'A szerelő a sárga autó fölé hajol, és megjavítja az elejét.'::text),
(295779,32865,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die zwei Autos stehen ... einer grünen Hecke.'::text,'vor'::text,'auf'::text,'an'::text,'Die zwei Autos stehen vor einer grünen Hecke.'::text),
(295783,32865,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дві машини стоять ... зеленим живоплотом.'::text,'перед'::text,'на'::text,'біля'::text,'Дві машини стоять перед зеленим живоплотом.'::text),
(295782,32865,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los dos coches están ... un seto verde.'::text,'delante de'::text,'sobre'::text,'a'::text,'Los dos coches están delante de un seto verde.'::text),
(295781,32865,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les deux voitures sont ... une haie verte.'::text,'devant'::text,'sur'::text,'à'::text,'Les deux voitures sont devant une haie verte.'::text),
(295784,32865,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki araba yeşil bir çitin ... duruyor.'::text,'önünde'::text,'üstünde'::text,NULL::text,'İki araba yeşil bir çitin önünde duruyor.'::text),
(295785,32865,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A két autó egy zöld ... áll.'::text,'sövény előtt'::text,'sövényen'::text,'sövénynél'::text,'A két autó egy zöld sövény előtt áll.'::text),
(295788,32866,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Autofronten berühren sich fast! Das ist eine Katastrophe!'::text,'Zwei'::text,'Zweite'::text,'Zweimal'::text,'Zwei Autofronten berühren sich fast! Das ist eine Katastrophe!'::text),
(295792,32866,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... передки машин майже торкаються! Це катастрофа!'::text,'Два'::text,'Другі'::text,'Двічі'::text,'Два передки машин майже торкаються! Це катастрофа!'::text),
(295791,32866,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... frontales de coche casi se tocan! ¡Esto es un desastre!'::text,'Dos'::text,'Segundos'::text,'Dos veces'::text,'¡Dos frontales de coche casi se tocan! ¡Esto es un desastre!'::text),
(295790,32866,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... avants de voiture se touchent presque ! C''est une catastrophe !'::text,'Deux'::text,'Deuxièmes'::text,'Deux fois'::text,'Deux avants de voiture se touchent presque ! C''est une catastrophe !'::text),
(295793,32866,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... araba burnu neredeyse birbirine değiyor! Bu bir felaket!'::text,'İki'::text,'İkinci'::text,'İki kez'::text,'İki araba burnu neredeyse birbirine değiyor! Bu bir felaket!'::text),
(295794,32866,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... autóorr majdnem összeér! Ez katasztrófa!'::text,'Két'::text,'Második'::text,'Kétszer'::text,'Két autóorr majdnem összeér! Ez katasztrófa!'::text),
(295806,32868,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, er hat mir gesagt, dass nicht ... Geld für eine neue gelbe Front da ist.'::text,'viel'::text,'viele'::text,'etwas'::text,'Hör zu, er hat mir gesagt, dass nicht viel Geld für eine neue gelbe Front da ist.'::text),
(295810,32868,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він сказав мені, що немає ... грошей на новий жовтий передок.'::text,'багато'::text,'багато'::text,'трохи'::text,'Слухай, він сказав мені, що немає багато грошей на новий жовтий передок.'::text),
(295809,32868,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me dijo que no hay ... dinero para un frontal amarillo nuevo.'::text,'mucho'::text,'muchos'::text,'algo de'::text,'Oye, me dijo que no hay mucho dinero para un frontal amarillo nuevo.'::text),
(295808,32868,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il m''a dit qu''il n''y a pas ... argent pour un nouvel avant jaune.'::text,'beaucoup d'''::text,'beaucoup d'''::text,'de l'''::text,'Écoute, il m''a dit qu''il n''y a pas beaucoup d'' argent pour un nouvel avant jaune.'::text),
(295811,32868,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana yeni sarı bir ön kısım için ... para olmadığını söyledi.'::text,'çok'::text,'çok'::text,'biraz'::text,'Dinle, bana yeni sarı bir ön kısım için çok para olmadığını söyledi.'::text),
(295812,32868,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy nincs ... pénz egy új sárga autóelejére.'::text,'sok'::text,'sok'::text,'némi'::text,'Figyelj, azt mondta, hogy nincs sok pénz egy új sárga autóelejére.'::text),
(295815,32869,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Da ... zwei alte Autos mit den Fronten ganz nah beieinander.'::text,'sind'::text,'ist'::text,'sein'::text,'Da sind zwei alte Autos mit den Fronten ganz nah beieinander.'::text),
(295819,32869,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тут ... дві старі машини, що стоять передками впритул.'::text,'є'::text,'є'::text,'бути'::text,'Тут є дві старі машини, що стоять передками впритул.'::text),
(295818,32869,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... dos coches viejos con los frontales juntos.'::text,'Hay'::text,'Hay'::text,'Hay'::text,'Hay dos coches viejos con los frontales juntos.'::text),
(295817,32869,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... deux vieilles voitures avec leurs avants collés.'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Il y a deux vieilles voitures avec leurs avants collés.'::text),
(295820,32869,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Önleri birbirine yapışık iki eski araba ...'::text,'var'::text,'var'::text,'olmak'::text,'Önleri birbirine yapışık iki eski araba var.'::text),
(295821,32869,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Két régi autó ... ott, összeérő elejükkel.'::text,'van'::text,'van'::text,'lenni'::text,'Két régi autó van ott, összeérő elejükkel.'::text),
(321789,35755,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... ewig über dieses gelbe Auto!'::text,'redet'::text,'redet'::text,'redet'::text,'Er redet ewig über dieses gelbe Auto!'::text),
(321793,35755,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... про ту жовту машину без кінця!'::text,'говорить'::text,'говорить'::text,'говорить'::text,'Він говорить про ту жовту машину без кінця!'::text),
(321792,35755,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... de ese coche amarillo sin parar!'::text,'Está hablando'::text,'Habla'::text,'Está hablando'::text,'¡Está hablando de ese coche amarillo sin parar!'::text),
(321791,35755,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... de cette voiture jaune sans fin !'::text,'est en train de parler'::text,'parle'::text,'est en train de parler'::text,'Il est en train de parler de cette voiture jaune sans fin !'::text),
(321794,35755,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O sarı araba hakkında durmadan ...!'::text,'konuşuyor'::text,'konuşur'::text,'konuşuyor'::text,'O sarı araba hakkında durmadan konuşuyor!'::text),
(321795,35755,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Örökké arról a sárga autóról ...!'::text,'beszél'::text,'beszél'::text,'beszél'::text,'Örökké arról a sárga autóról beszél!'::text),
(321798,35756,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er redet nie, aber jetzt ... er absolut ohne Pause!'::text,'redet'::text,'redet'::text,NULL::text,'Er redet nie, aber jetzt redet er absolut ohne Pause!'::text),
(321802,35756,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ніколи не говорить, а зараз ... абсолютно без упину!'::text,'говорить'::text,'говорить'::text,NULL::text,'Він ніколи не говорить, а зараз говорить абсолютно без упину!'::text),
(321801,35756,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nunca habla, ¡pero ahora ... sin parar!'::text,'está hablando'::text,'habla'::text,NULL::text,'Nunca habla, ¡pero ahora está hablando sin parar!'::text),
(321800,35756,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ne parle jamais, mais là il ... absolument non-stop !'::text,'est en train de parler'::text,'parle'::text,NULL::text,'Il ne parle jamais, mais là il est en train de parler absolument non-stop !'::text),
(321803,35756,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hiç konuşmaz ama şimdi kesinlikle durmadan ...!'::text,'konuşuyor'::text,'konuşur'::text,NULL::text,'Hiç konuşmaz ama şimdi kesinlikle durmadan konuşuyor!'::text),
(321804,35756,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Soha nem beszél, de most abszolút megállás nélkül ...!'::text,'beszél'::text,'beszél'::text,NULL::text,'Soha nem beszél, de most abszolút megállás nélkül beszél!'::text),
(321807,35757,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, meine Schwester sagt, dass er morgen wieder über dieses Auto ...'::text,'reden wird'::text,'redet'::text,'redete'::text,'Bestie, meine Schwester sagt, dass er morgen wieder über dieses Auto reden wird.'::text),
(321811,35757,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подружко, моя сестра каже, що завтра він знову ... про ту машину.'::text,'говоритиме'::text,'говорить'::text,'говорив'::text,'Подружко, моя сестра каже, що завтра він знову говоритиме про ту машину.'::text),
(321810,35757,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, mi hermana dice que mañana ... otra vez de ese coche.'::text,'hablará'::text,'habla'::text,'habló'::text,'Amiga, mi hermana dice que mañana hablará otra vez de ese coche.'::text),
(321809,35757,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, ma sœur dit qu''il ... encore de cette voiture demain.'::text,'parlera'::text,'parle'::text,'a parlé'::text,'Ma belle, ma sœur dit qu''il parlera encore de cette voiture demain.'::text),
(321812,35757,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, kız kardeşim diyor ki yarın yine o araba hakkında ...'::text,'konuşacak'::text,'konuşur'::text,'konuştu'::text,'Kanka, kız kardeşim diyor ki yarın yine o araba hakkında konuşacak.'::text),
(321813,35757,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, a nővérem szerint holnap megint arról az autóról ...'::text,'fog beszélni'::text,'beszél'::text,'beszélt'::text,'Csajszi, a nővérem szerint holnap megint arról az autóról fog beszélni.'::text),
(321816,35758,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, er hat mir gesagt, dass er in einem Video über sein Auto ...'::text,'reden wird'::text,'reden wird'::text,'redet'::text,'Hör zu, er hat mir gesagt, dass er in einem Video über sein Auto reden wird.'::text),
(321820,35758,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він сказав мені, що ... про свою машину у відео.'::text,'збирається розповісти'::text,'розповість'::text,'розповідає'::text,'Слухай, він сказав мені, що збирається розповісти про свою машину у відео.'::text),
(321819,35758,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me dijo que ... de su coche en un vídeo.'::text,'va a hablar'::text,'hablará'::text,'habla'::text,'Oye, me dijo que va a hablar de su coche en un vídeo.'::text),
(321818,35758,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il m''a dit qu''il ... de sa voiture dans une vidéo.'::text,'va parler'::text,'parlera'::text,'parle'::text,'Écoute, il m''a dit qu''il va parler de sa voiture dans une vidéo.'::text),
(321821,35758,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana dedi ki bir videoda arabası hakkında ...'::text,'konuşacak'::text,'konuşacak'::text,'konuşur'::text,'Dinle, bana dedi ki bir videoda arabası hakkında konuşacak.'::text),
(321822,35758,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy egy videóban ... az autójáról.'::text,'fog beszélni'::text,'fog beszélni'::text,'beszél'::text,'Figyelj, azt mondta, hogy egy videóban fog beszélni az autójáról.'::text),
(321825,35759,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hast nach dem Auto gefragt? Klar, ich ... darüber reden, Alter.'::text,'werde'::text,'werde'::text,NULL::text,'Du hast nach dem Auto gefragt? Klar, ich werde darüber reden, Alter.'::text),
(321829,35759,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Питав про машину? Без питань, я ... про неї, бро.'::text,'розповім'::text,'збираюся розповісти'::text,NULL::text,'Питав про машину? Без питань, я розповім про неї, бро.'::text),
(321828,35759,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿Preguntaste por el coche? Hecho, ... de él, tío.'::text,'hablaré'::text,'voy a hablar'::text,NULL::text,'¿Preguntaste por el coche? Hecho, hablaré de él, tío.'::text),
(321827,35759,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu as demandé pour la voiture ? Carrément, je ... d''elle, frère.'::text,'parlerai'::text,'vais parler'::text,NULL::text,'Tu as demandé pour la voiture ? Carrément, je parlerai d''elle, frère.'::text),
(321830,35759,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arabayı mı sordun? Tamamdır, onun hakkında ..., kanka.'::text,'konuşacağım'::text,'konuşacağım'::text,NULL::text,'Arabayı mı sordun? Tamamdır, onun hakkında konuşacağım, kanka.'::text),
(321831,35759,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az autóról kérdeztél? Oké, ... róla, tesó.'::text,'beszélni fogok'::text,'beszélni fogok'::text,NULL::text,'Az autóról kérdeztél? Oké, beszélni fogok róla, tesó.'::text),
(321834,35760,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Interview hat eine Regel, also ... er über das Auto reden.'::text,'muss'::text,'muss'::text,'muss nicht'::text,'Das Interview hat eine Regel, also muss er über das Auto reden.'::text),
(321838,35760,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'В інтерв''ю є правило, тож він ... говорити про машину.'::text,'має'::text,'мусить'::text,'не мусить'::text,'В інтерв''ю є правило, тож він має говорити про машину.'::text),
(321837,35760,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La entrevista tiene una regla, así que ... hablar del coche.'::text,'tiene que'::text,'debe'::text,'no tiene que'::text,'La entrevista tiene una regla, así que tiene que hablar del coche.'::text),
(321836,35760,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''interview a une règle, donc il ... parler de la voiture.'::text,'doit'::text,'doit'::text,'n''a pas à'::text,'L''interview a une règle, donc il doit parler de la voiture.'::text),
(321839,35760,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Röportajın bir kuralı var, bu yüzden araba hakkında ...'::text,'konuşmak zorunda'::text,'konuşmalı'::text,'konuşmak zorunda değil'::text,'Röportajın bir kuralı var, bu yüzden araba hakkında konuşmak zorunda.'::text),
(321840,35760,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az interjúnak van egy szabálya, ezért az autóról ... beszélnie.'::text,'kell'::text,'kell'::text,'nem kell'::text,'Az interjúnak van egy szabálya, ezért az autóról kell beszélnie.'::text),
(321852,35762,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein stiller Mann, klar: Er redet, ... das Auto seine große Liebe ist.'::text,'weil'::text,'aber'::text,'also'::text,'Ein stiller Mann, klar: Er redet, weil das Auto seine große Liebe ist.'::text),
(321856,35762,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тихий чоловік, авжеж: він говорить, ... машина — його велике кохання.'::text,'бо'::text,'але'::text,'тому'::text,'Тихий чоловік, авжеж: він говорить, бо машина — його велике кохання.'::text),
(321855,35762,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un hombre callado, claro: habla ... el coche es su gran amor.'::text,'porque'::text,'pero'::text,'así que'::text,'Un hombre callado, claro: habla porque el coche es su gran amor.'::text),
(321854,35762,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un homme discret, évidemment : il parle ... la voiture est son grand amour.'::text,'parce que'::text,'mais'::text,'donc'::text,'Un homme discret, évidemment : il parle parce que la voiture est son grand amour.'::text),
(321857,35762,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sessiz bir adam, belli ki: konuşuyor ... araba onun büyük aşkı.'::text,'çünkü'::text,'ama'::text,'bu yüzden'::text,'Sessiz bir adam, belli ki: konuşuyor çünkü araba onun büyük aşkı.'::text),
(321858,35762,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csendes ember, nyilván: beszél, ... az autó a nagy szerelme.'::text,'mert'::text,'de'::text,'ezért'::text,'Csendes ember, nyilván: beszél, mert az autó a nagy szerelme.'::text),
(318639,35405,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, dieses Auto ... so viel Tempo, ich muss mich festhalten.'::text,'hat'::text,'haben'::text,'hat'::text,'Alter, dieses Auto hat so viel Tempo, ich muss mich festhalten.'::text),
(318643,35405,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ця машина ... таку швидкість, треба триматися.'::text,'має'::text,'мати'::text,'має'::text,'Бро, ця машина має таку швидкість, треба триматися.'::text),
(318642,35405,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, este coche ... tanta velocidad que tengo que agarrarme.'::text,'tiene'::text,'tienen'::text,'tiene'::text,'Tío, este coche tiene tanta velocidad que tengo que agarrarme.'::text),
(318641,35405,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, cette voiture ... tellement de vitesse, faut que je m''accroche.'::text,'a'::text,'ont'::text,'a'::text,'Frère, cette voiture a tellement de vitesse, faut que je m''accroche.'::text),
(318644,35405,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu arabanın o kadar çok hızı ... ki sıkı tutunmam lazım.'::text,'var'::text,'var'::text,'var'::text,'Kanka, bu arabanın o kadar çok hızı var ki sıkı tutunmam lazım.'::text),
(318645,35405,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ennek az autónak akkora sebessége ..., kapaszkodnom kell.'::text,'van'::text,'van'::text,'van'::text,'Tesó, ennek az autónak akkora sebessége van, kapaszkodnom kell.'::text),
(318657,35407,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Zielgeschwindigkeit ist 300 km/h, und das Auto ... es schaffen.'::text,'kann'::text,'kann'::text,'ist'::text,'Die Zielgeschwindigkeit ist 300 km/h, und das Auto kann es schaffen.'::text),
(318661,35407,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цільова швидкість — 300 км/год, і машина ... це зробити.'::text,'може'::text,'може'::text,'є'::text,'Цільова швидкість — 300 км/год, і машина може це зробити.'::text),
(318660,35407,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La velocidad objetivo es de 300 km/h, y el coche ... conseguirlo.'::text,'puede'::text,'puede'::text,'está'::text,'La velocidad objetivo es de 300 km/h, y el coche puede conseguirlo.'::text),
(318659,35407,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La vitesse cible est de 300 km/h, et la voiture ... y arriver.'::text,'peut'::text,'peut'::text,'est'::text,'La vitesse cible est de 300 km/h, et la voiture peut y arriver.'::text),
(318662,35407,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hedef hız 300 km/sa ve araba bunu ...'::text,'başarabilir'::text,'başarabilir'::text,NULL::text,'Hedef hız 300 km/sa ve araba bunu başarabilir.'::text),
(318663,35407,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A célsebesség 300 km/h, és az autó ... ezt.'::text,'tudja'::text,'tudja'::text,'van'::text,'A célsebesség 300 km/h, és az autó tudja ezt.'::text),
(318666,35408,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Auto fährt mit hohem Tempo durch zwei ...'::text,'Kurven'::text,'Kurve'::text,'Kurven'::text,'Das Auto fährt mit hohem Tempo durch zwei Kurven.'::text),
