(304244,33805,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ayıya bir bakış atıyor çünkü orada.'::text,'Şu'::text,'Şu'::text,'Bu'::text,'Şu ayıya bir bakış atıyor çünkü orada.'::text),
(304245,33805,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ránéz ... a medvére, mert ott van.'::text,'arra'::text,'azokra'::text,'ezekre'::text,'Ránéz arra a medvére, mert ott van.'::text),
(304248,33806,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du bist so entspannt. Ehrlich, ich mag ... Blick auf den Bären.'::text,'deinen'::text,'seinen'::text,'du'::text,'Du bist so entspannt. Ehrlich, ich mag deinen Blick auf den Bären.'::text),
(304252,33806,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти такий спокійний. Чесно, мені подобається ... погляд на ведмедя.'::text,'твій'::text,'його'::text,'ти'::text,'Ти такий спокійний. Чесно, мені подобається твій погляд на ведмедя.'::text),
(304251,33806,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Estás tan tranquilo. Me gusta ... mirada al oso, la verdad.'::text,'tu'::text,'su'::text,'tú'::text,'Estás tan tranquilo. Me gusta tu mirada al oso, la verdad.'::text),
(304250,33806,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu es tellement calme. J''aime ... regard sur l''ours, franchement.'::text,'ton'::text,'son'::text,'toi'::text,'Tu es tellement calme. J''aime ton regard sur l''ours, franchement.'::text),
(304253,33806,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çok sakinsin. Açıkçası ayıya ... bakışını seviyorum.'::text,'senin'::text,'onun'::text,'sen'::text,'Çok sakinsin. Açıkçası ayıya senin bakışını seviyorum.'::text),
(304254,33806,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Olyan nyugodt vagy. Őszintén, tetszik a medvére vetett ...'::text,'pillantásod'::text,'pillantása'::text,'te'::text,'Olyan nyugodt vagy. Őszintén, tetszik a medvére vetett pillantásod.'::text),
(304257,33807,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ist der Bär? Direkt neben dir. Dieser Blick ist legendär.'::text,'Wo'::text,'Wer'::text,'Was'::text,'Wo ist der Bär? Direkt neben dir. Dieser Blick ist legendär.'::text),
(304261,33807,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ведмідь? Прямо поруч із тобою. Цей погляд — легенда.'::text,'Де'::text,'Хто'::text,'Що'::text,'Де ведмідь? Прямо поруч із тобою. Цей погляд — легенда.'::text),
(304260,33807,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... está el oso? Justo a tu lado. Esa mirada es icónica.'::text,'Dónde'::text,'Quién'::text,'Qué'::text,'¿Dónde está el oso? Justo a tu lado. Esa mirada es icónica.'::text),
(304259,33807,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... est l''ours ? Juste à côté de toi. Ce regard est iconique.'::text,'Où'::text,'Qui'::text,'Que'::text,'Où est l''ours ? Juste à côté de toi. Ce regard est iconique.'::text),
(304262,33807,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ayı ...? Tam yanında. O bakış efsane.'::text,'nerede'::text,'kim'::text,'ne'::text,'Ayı nerede? Tam yanında. O bakış efsane.'::text),
(304263,33807,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... van a medve? Közvetlenül melletted. Ez a pillantás ikonikus.'::text,'Hol'::text,'Ki'::text,'Mi'::text,'Hol van a medve? Közvetlenül melletted. Ez a pillantás ikonikus.'::text),
(304266,33808,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Schau dich an, wie du ... einem Kanu sitzt und dem Bären einen Blick zuwirfst.'::text,'in'::text,'an'::text,'unter'::text,'Schau dich an, wie du in einem Kanu sitzt und dem Bären einen Blick zuwirfst.'::text),
(304270,33808,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти лише поглянь на себе: сидиш ... каное й кидаєш погляд на ведмедя.'::text,'у'::text,'біля'::text,'під'::text,'Ти лише поглянь на себе: сидиш у каное й кидаєш погляд на ведмедя.'::text),
(304269,33808,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mírate, sentado ... una canoa y echándole una mirada al oso.'::text,'en'::text,'a'::text,'debajo de'::text,'Mírate, sentado en una canoa y echándole una mirada al oso.'::text),
(304268,33808,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Regarde-toi, assis ... un canoë à jeter un regard à l''ours.'::text,'dans'::text,'à'::text,'sous'::text,'Regarde-toi, assis dans un canoë à jeter un regard à l''ours.'::text),
(304271,33808,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu haline bak, bir kanonun ... oturmuş ayıya bakış atıyorsun.'::text,'içinde'::text,NULL::text,'altında'::text,'Şu haline bak, bir kanonun içinde oturmuş ayıya bakış atıyorsun.'::text),
(304272,33808,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nézz magadra, ahogy egy ... ülsz, és a medvére pillantasz.'::text,'kenuban'::text,'kenunál'::text,'kenu alatt'::text,'Nézz magadra, ahogy egy kenuban ülsz, és a medvére pillantasz.'::text),
(304275,33809,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Bären bekommen einen langen Blick von dem Mann.'::text,'Zwei'::text,'Zweite'::text,'Zweimal'::text,'Zwei Bären bekommen einen langen Blick von dem Mann.'::text),
(304279,33809,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ведмеді отримують від чоловіка один довгий погляд.'::text,'Два'::text,'Другі'::text,'Двічі'::text,'Два ведмеді отримують від чоловіка один довгий погляд.'::text),
(304278,33809,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... osos reciben una larga mirada del hombre.'::text,'Dos'::text,'Segundos'::text,'Dos veces'::text,'Dos osos reciben una larga mirada del hombre.'::text),
(304277,33809,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ours reçoivent un long regard de l''homme.'::text,'Deux'::text,'Deuxièmes'::text,'Deux fois'::text,'Deux ours reçoivent un long regard de l''homme.'::text),
(304280,33809,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ayı adamdan uzun bir bakış alıyor.'::text,'İki'::text,'İkinci'::text,'İki kez'::text,'İki ayı adamdan uzun bir bakış alıyor.'::text),
(304281,33809,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... medve kap egy hosszú pillantást a férfitól.'::text,'Két'::text,'Második'::text,'Kétszer'::text,'Két medve kap egy hosszú pillantást a férfitól.'::text),
(314310,34924,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Henne ... schwimmen, also rettet sie das Küken.'::text,'kann'::text,'kann'::text,'ist'::text,'Die Henne kann schwimmen, also rettet sie das Küken.'::text),
(314314,34924,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Курка ... плавати, тож рятує курча.'::text,'може'::text,'може'::text,'є'::text,'Курка може плавати, тож рятує курча.'::text),
(314313,34924,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La gallina ... nadar, así que salva al pollito.'::text,'puede'::text,'puede'::text,'está'::text,'La gallina puede nadar, así que salva al pollito.'::text),
(314312,34924,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La poule ... nager, donc elle sauve le poussin.'::text,'peut'::text,'peut'::text,'est'::text,'La poule peut nager, donc elle sauve le poussin.'::text),
(314315,34924,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tavuk ..., bu yüzden civcivi kurtarıyor.'::text,'yüzebilir'::text,'yüzebilir'::text,NULL::text,'Tavuk yüzebilir, bu yüzden civcivi kurtarıyor.'::text),
(314316,34924,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tyúk ... úszni, ezért megmenti a csibét.'::text,'tud'::text,'tud'::text,'van'::text,'A tyúk tud úszni, ezért megmenti a csibét.'::text),
(314319,34925,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Entspannter Spaziergang, klar. Keine Sorge, Mama ... dich retten, kleines Küken.'::text,'wird'::text,'rettet'::text,'rettete'::text,'Entspannter Spaziergang, klar. Keine Sorge, Mama wird dich retten, kleines Küken.'::text),
(314323,34925,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Спокійна прогулянка, авжеж. Не бійся, мама тебе ..., курчатко.'::text,'врятує'::text,'рятує'::text,'врятувала'::text,'Спокійна прогулянка, авжеж. Не бійся, мама тебе врятує, курчатко.'::text),
(314322,34925,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Paseo relajante, claro. Tranquilo, mamá te ..., pollito.'::text,'salvará'::text,'salva'::text,'salvó'::text,'Paseo relajante, claro. Tranquilo, mamá te salvará, pollito.'::text),
(314321,34925,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Balade relaxante, évidemment. T''inquiète, maman te ..., petit poussin.'::text,'sauvera'::text,'sauve'::text,'a sauvé'::text,'Balade relaxante, évidemment. T''inquiète, maman te sauvera, petit poussin.'::text),
(314324,34925,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rahatlatıcı bir yürüyüş, belli ki. Merak etme, annen seni ..., küçük civciv.'::text,'kurtaracak'::text,'kurtarır'::text,'kurtardı'::text,'Rahatlatıcı bir yürüyüş, belli ki. Merak etme, annen seni kurtaracak, küçük civciv.'::text),
(314325,34925,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pihentető séta, nyilván. Ne aggódj, anya ..., kiscsibe.'::text,'meg fog menteni'::text,'megment'::text,'megmentett'::text,'Pihentető séta, nyilván. Ne aggódj, anya meg fog menteni, kiscsibe.'::text),
(314328,34926,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Küken ist reingefallen, Alter, also ... die Henne es retten, ohne Scheiß.'::text,'wird'::text,'wird'::text,'rettet'::text,'Das Küken ist reingefallen, Alter, also wird die Henne es retten, ohne Scheiß.'::text),
(314332,34926,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Курча впало, бро, тож курка ... його, чесно.'::text,'збирається врятувати'::text,'врятує'::text,'рятує'::text,'Курча впало, бро, тож курка збирається врятувати його, чесно.'::text),
(314331,34926,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El pollito se cayó, tío, así que la gallina lo ..., en serio.'::text,'va a salvar'::text,'salvará'::text,'salva'::text,'El pollito se cayó, tío, así que la gallina lo va a salvar, en serio.'::text),
(314330,34926,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le poussin est tombé, frère, donc la poule ..., sans mentir.'::text,'va le sauver'::text,'le sauvera'::text,'le sauve'::text,'Le poussin est tombé, frère, donc la poule va le sauver, sans mentir.'::text),
(314333,34926,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Civciv suya düştü, kanka, bu yüzden tavuk onu ..., yemin ederim.'::text,'kurtaracak'::text,'kurtaracak'::text,'kurtarır'::text,'Civciv suya düştü, kanka, bu yüzden tavuk onu kurtaracak, yemin ederim.'::text),
(314334,34926,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csibe beleesett, tesó, szóval a tyúk ..., komolyan.'::text,'meg fogja menteni'::text,'meg fogja menteni'::text,'megmenti'::text,'A csibe beleesett, tesó, szóval a tyúk meg fogja menteni, komolyan.'::text),
(314346,34928,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sicherheitsrichtlinie: Die Henne ... jedes Küken retten, alle 4.'::text,'muss'::text,'muss'::text,'muss nicht'::text,'Sicherheitsrichtlinie: Die Henne muss jedes Küken retten, alle 4.'::text),
(314350,34928,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Політика безпеки: курка ... врятувати кожне курча, всіх 4.'::text,'має'::text,'мусить'::text,'не мусить'::text,'Політика безпеки: курка має врятувати кожне курча, всіх 4.'::text),
(314349,34928,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Política de seguridad: la gallina ... salvar a cada pollito, a los 4.'::text,'tiene que'::text,'debe'::text,'no tiene que'::text,'Política de seguridad: la gallina tiene que salvar a cada pollito, a los 4.'::text),
(314348,34928,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Politique de sécurité : la poule ... sauver chaque poussin, les 4.'::text,'doit'::text,'doit'::text,'n''a pas à'::text,'Politique de sécurité : la poule doit sauver chaque poussin, les 4.'::text),
(314351,34928,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Güvenlik politikası: tavuk her civcivi, 4''ünü de ...'::text,'kurtarmak zorunda'::text,'kurtarmalı'::text,'kurtarmak zorunda değil'::text,'Güvenlik politikası: tavuk her civcivi, 4''ünü de kurtarmak zorunda.'::text),
(314352,34928,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Biztonsági szabályzat: a tyúknak minden csibét meg ... mentenie, mind a 4-et.'::text,'kell'::text,'kell'::text,'nem kell'::text,'Biztonsági szabályzat: a tyúknak minden csibét meg kell mentenie, mind a 4-et.'::text),
(314355,34929,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Eis bricht, also ... die Henne ihr Küken schnell retten.'::text,'sollte'::text,'sollte'::text,'soll'::text,'Das Eis bricht, also sollte die Henne ihr Küken schnell retten.'::text),
(314359,34929,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Лід тріщить, тож курка ... швидко врятувати своє курча.'::text,'мала б'::text,'мала б'::text,'буде'::text,'Лід тріщить, тож курка мала б швидко врятувати своє курча.'::text),
(314358,34929,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hielo se agrieta, así que la gallina ... salvar rápido a su pollito.'::text,'debería'::text,'debería'::text,'deberá'::text,'El hielo se agrieta, así que la gallina debería salvar rápido a su pollito.'::text),
(314357,34929,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La glace craque, donc la poule ... sauver vite son poussin.'::text,'devrait'::text,'devrait'::text,'devra'::text,'La glace craque, donc la poule devrait sauver vite son poussin.'::text),
(314360,34929,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buz çatlıyor, bu yüzden tavuk civcivini hemen ...'::text,'kurtarmalı'::text,'kurtarmalı'::text,'kurtaracak'::text,'Buz çatlıyor, bu yüzden tavuk civcivini hemen kurtarmalı.'::text),
(314361,34929,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Reped a jég, ezért a tyúknak gyorsan meg ... mentenie a csibéjét.'::text,'kellene'::text,'kellene'::text,'kell'::text,'Reped a jég, ezért a tyúknak gyorsan meg kellene mentenie a csibéjét.'::text),
(314364,34930,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Küken fällt hinein, ... taucht die Henne, um es zu retten.'::text,'also'::text,'aber'::text,'weil'::text,'Das Küken fällt hinein, also taucht die Henne, um es zu retten.'::text),
(314368,34930,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Курча падає у воду, ... курка пірнає, щоб його врятувати.'::text,'тому'::text,'але'::text,'бо'::text,'Курча падає у воду, тому курка пірнає, щоб його врятувати.'::text),
(314367,34930,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El pollito se cae, ... la gallina se zambulle para salvarlo.'::text,'así que'::text,'pero'::text,'porque'::text,'El pollito se cae, así que la gallina se zambulle para salvarlo.'::text),
(314366,34930,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le poussin tombe dedans, ... la poule plonge pour le sauver.'::text,'donc'::text,'mais'::text,'parce que'::text,'Le poussin tombe dedans, donc la poule plonge pour le sauver.'::text),
(314369,34930,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Civciv suya düşüyor, ... tavuk onu kurtarmak için dalıyor.'::text,'bu yüzden'::text,'ama'::text,'çünkü'::text,'Civciv suya düşüyor, bu yüzden tavuk onu kurtarmak için dalıyor.'::text),
(314370,34930,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csibe beleesik, ... a tyúk utánaveti magát, hogy megmentse.'::text,'ezért'::text,'de'::text,'mert'::text,'A csibe beleesik, ezért a tyúk utánaveti magát, hogy megmentse.'::text),
(305877,33987,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Habicht füttert diese Mäuler täglich, aber gestern ... eine Henne sie. Verrat!'::text,'fütterte'::text,'füttert'::text,NULL::text,'Der Habicht füttert diese Mäuler täglich, aber gestern fütterte eine Henne sie. Verrat!'::text),
(305881,33987,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Яструб годує ці ротики щодня, але вчора їх ... курка. Зрада!'::text,'нагодувала'::text,'годує'::text,NULL::text,'Яструб годує ці ротики щодня, але вчора їх нагодувала курка. Зрада!'::text),
(305880,33987,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El halcón alimenta estas bocas a diario, pero ayer las ... una gallina. ¡Traición!'::text,'alimentó'::text,'alimenta'::text,NULL::text,'El halcón alimenta estas bocas a diario, pero ayer las alimentó una gallina. ¡Traición!'::text),
(305879,33987,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le faucon nourrit ces becs tous les jours, mais hier une poule les ... ! Trahison !'::text,'a nourris'::text,'nourrit'::text,NULL::text,'Le faucon nourrit ces becs tous les jours, mais hier une poule les a nourris ! Trahison !'::text),
(305882,33987,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şahin bu ağızları her gün besler, ama dün onları bir tavuk ...! İhanet!'::text,'besledi'::text,'besler'::text,NULL::text,'Şahin bu ağızları her gün besler, ama dün onları bir tavuk besledi! İhanet!'::text),
(305883,33987,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A héja naponta eteti ezeket a szájakat, de tegnap egy tyúk ... meg őket. Árulás!'::text,'etette'::text,'eteti'::text,NULL::text,'A héja naponta eteti ezeket a szájakat, de tegnap egy tyúk etette meg őket. Árulás!'::text),
(305886,33988,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Schau! Drei hungrige Mäuler ... auf das Korn. Chaos!'::text,'warten'::text,'wartet'::text,'warten'::text,'Schau! Drei hungrige Mäuler warten auf das Korn. Chaos!'::text),
(305890,33988,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дивись! Три голодні ротики ... на зерно. Хаос!'::text,'чекають'::text,'чекає'::text,'чекають'::text,'Дивись! Три голодні ротики чекають на зерно. Хаос!'::text),
(305889,33988,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Mira! Tres bocas hambrientas ... el grano. ¡Caos!'::text,'están esperando'::text,'espera'::text,'están esperando'::text,'¡Mira! Tres bocas hambrientas están esperando el grano. ¡Caos!'::text),
(305888,33988,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Regarde ! Trois becs affamés ... le grain. Chaos !'::text,'sont en train d''attendre'::text,'attend'::text,'sont en train d''attendre'::text,'Regarde ! Trois becs affamés sont en train d''attendre le grain. Chaos !'::text),
(305891,33988,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bak! Üç aç ağız tahılı ...! Kaos!'::text,'bekliyor'::text,'bekler'::text,'bekliyor'::text,'Bak! Üç aç ağız tahılı bekliyor! Kaos!'::text),
(305892,33988,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nézd! Három éhes száj ... a magokra. Káosz!'::text,'vár'::text,'vár'::text,'vár'::text,'Nézd! Három éhes száj vár a magokra. Káosz!'::text),
(305895,33989,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sonst frisst sie Körner, aber heute ... sie drei Mäuler, weil Mäuler fressen.'::text,'füttert'::text,'füttert'::text,NULL::text,'Sonst frisst sie Körner, aber heute füttert sie drei Mäuler, weil Mäuler fressen.'::text),
(305899,33989,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай вона їсть зерно, але сьогодні вона ... три ротики, бо ротики їдять.'::text,'годує'::text,'годує'::text,NULL::text,'Зазвичай вона їсть зерно, але сьогодні вона годує три ротики, бо ротики їдять.'::text),
(305898,33989,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente come grano, pero hoy ... a tres bocas, porque las bocas comen.'::text,'está alimentando'::text,'alimenta'::text,NULL::text,'Normalmente come grano, pero hoy está alimentando a tres bocas, porque las bocas comen.'::text),
(305897,33989,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude elle mange du grain, mais aujourd''hui elle ... trois becs, parce que les becs mangent.'::text,'est en train de nourrir'::text,'nourrit'::text,NULL::text,'D''habitude elle mange du grain, mais aujourd''hui elle est en train de nourrir trois becs, parce que les becs mangent.'::text),
(305900,33989,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde tahıl yer ama bugün üç ağzı ..., çünkü ağızlar yemek yer.'::text,'besliyor'::text,'besler'::text,NULL::text,'Genelde tahıl yer ama bugün üç ağzı besliyor, çünkü ağızlar yemek yer.'::text),
(305901,33989,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában magot eszik, de ma három szájat ..., mert a szájak esznek.'::text,'etet'::text,'etet'::text,NULL::text,'Általában magot eszik, de ma három szájat etet, mert a szájak esznek.'::text),
(305904,33990,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen ... die Henne diese Mäuler wieder füttern, weil morgen nach heute ist.'::text,'wird'::text,'fütterte'::text,'fütternd'::text,'Morgen wird die Henne diese Mäuler wieder füttern, weil morgen nach heute ist.'::text),
(305908,33990,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра курка знову ... ці ротики, бо завтра буде після сьогодні.'::text,'нагодує'::text,'нагодувала'::text,'годуючи'::text,'Завтра курка знову нагодує ці ротики, бо завтра буде після сьогодні.'::text),
(305907,33990,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana la gallina ... otra vez a estas bocas, porque mañana va después de hoy.'::text,'alimentará'::text,'alimentó'::text,'alimentando'::text,'Mañana la gallina alimentará otra vez a estas bocas, porque mañana va después de hoy.'::text),
(305906,33990,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain, la poule ... encore ces becs, parce que demain vient après aujourd''hui.'::text,'nourrira'::text,'a nourri'::text,'nourrissant'::text,'Demain, la poule nourrira encore ces becs, parce que demain vient après aujourd''hui.'::text),
(305909,33990,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın tavuk bu ağızları yine ..., çünkü yarın bugünden sonra gelir.'::text,'besleyecek'::text,'besledi'::text,'besleyerek'::text,'Yarın tavuk bu ağızları yine besleyecek, çünkü yarın bugünden sonra gelir.'::text),
(305910,33990,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap a tyúk újra ... ezeket a szájakat, mert a holnap a ma után jön.'::text,'etetni fogja'::text,'etette'::text,'etetve'::text,'Holnap a tyúk újra etetni fogja ezeket a szájakat, mert a holnap a ma után jön.'::text),
(305913,33991,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, anscheinend hat die Henne einen Plan: Sie ... jedes hungrige Maul füttern.'::text,'wird'::text,'wird'::text,'füttert'::text,'Rate mal, anscheinend hat die Henne einen Plan: Sie wird jedes hungrige Maul füttern.'::text),
(305917,33991,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, кажуть, у курки є план: вона ... кожен голодний ротик.'::text,'збирається нагодувати'::text,'нагодує'::text,'годує'::text,'Уяви, кажуть, у курки є план: вона збирається нагодувати кожен голодний ротик.'::text),
(305916,33991,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿Sabes qué? Parece que la gallina tiene un plan: ... a cada boca hambrienta.'::text,'va a alimentar'::text,'alimentará'::text,'alimenta'::text,'¿Sabes qué? Parece que la gallina tiene un plan: va a alimentar a cada boca hambrienta.'::text),
(305915,33991,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, apparemment la poule a un plan : elle ... chaque bec affamé.'::text,'va nourrir'::text,'nourrira'::text,'nourrit'::text,'Devine quoi, apparemment la poule a un plan : elle va nourrir chaque bec affamé.'::text),
(305918,33991,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım ne oldu, tavuğun bir planı varmış: her aç ağzı ...'::text,'besleyecek'::text,'besleyecek'::text,'besler'::text,'Bil bakalım ne oldu, tavuğun bir planı varmış: her aç ağzı besleyecek.'::text),
(305919,33991,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, a tyúknak állítólag van egy terve: ... minden éhes szájat.'::text,'meg fog etetni'::text,'meg fog etetni'::text,'megetet'::text,'Képzeld, a tyúknak állítólag van egy terve: meg fog etetni minden éhes szájat.'::text),
(305922,33992,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, sie hat gesagt, die Henne ist schon auf dem Felsvorsprung, also ... die Mäuler Körner bekommen.'::text,'werden'::text,'werden'::text,NULL::text,'Hör zu, sie hat gesagt, die Henne ist schon auf dem Felsvorsprung, also werden die Mäuler Körner bekommen.'::text),
(305926,33992,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, вона сказала, що курка вже на виступі, тож ті ротики ... зерно.'::text,'збираються отримати'::text,'отримають'::text,NULL::text,'Слухай, вона сказала, що курка вже на виступі, тож ті ротики збираються отримати зерно.'::text),
(305925,33992,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, dijo que la gallina ya está en la cornisa, así que esas bocas ... grano.'::text,'van a recibir'::text,'recibirán'::text,NULL::text,'Oye, dijo que la gallina ya está en la cornisa, así que esas bocas van a recibir grano.'::text),
(305924,33992,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, elle a dit que la poule est déjà sur la corniche, donc ces becs ... du grain.'::text,'vont recevoir'::text,'recevront'::text,NULL::text,'Écoute, elle a dit que la poule est déjà sur la corniche, donc ces becs vont recevoir du grain.'::text),
(305927,33992,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, tavuğun zaten çıkıntıda olduğunu söyledi, yani o ağızlar tahıl ...'::text,'alacak'::text,'alacak'::text,NULL::text,'Dinle, tavuğun zaten çıkıntıda olduğunu söyledi, yani o ağızlar tahıl alacak.'::text),
(305928,33992,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, a tyúk már a párkányon van, szóval azok a szájak magot ... kapni.'::text,'fognak'::text,'fognak'::text,NULL::text,'Figyelj, azt mondta, a tyúk már a párkányon van, szóval azok a szájak magot fognak kapni.'::text),
(305931,33993,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Für die drei offenen Mäuler ist nicht mehr viel ... übrig.'::text,'Korn'::text,'Korn'::text,'Samen'::text,'Für die drei offenen Mäuler ist nicht mehr viel Korn übrig.'::text),
(305935,33993,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Для трьох роззявлених ротиків не залишилося багато ...'::text,'зерна'::text,'зерна'::text,'насінин'::text,'Для трьох роззявлених ротиків не залишилося багато зерна.'::text),
(305934,33993,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No queda mucho ... para las tres bocas abiertas.'::text,'grano'::text,'grano'::text,'semillas'::text,'No queda mucho grano para las tres bocas abiertas.'::text),
(305933,33993,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ne reste plus beaucoup de ... pour les trois becs ouverts.'::text,'grain'::text,'grain'::text,'graines'::text,'Il ne reste plus beaucoup de grain pour les trois becs ouverts.'::text),
(305936,33993,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Üç açık ağız için çok fazla ... kalmadı.'::text,'tahıl'::text,'tahıllar'::text,'tohumlar'::text,'Üç açık ağız için çok fazla tahıl kalmadı.'::text),
(305937,33993,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem sok ... maradt a három tátott szájnak.'::text,'gabona'::text,'gabona'::text,'mag'::text,'Nem sok gabona maradt a három tátott szájnak.'::text),
(306921,34103,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Budget: 40 Euro. Ein Freund ... ihr eine große blaue Torte an.'::text,'bietet'::text,'bieten'::text,'anbietend'::text,'Budget: 40 Euro. Ein Freund bietet ihr eine große blaue Torte an.'::text),
(306925,34103,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бюджет: 40 євро. Друг ... їй великий синій торт.'::text,'пропонує'::text,'пропонувати'::text,'пропонуючи'::text,'Бюджет: 40 євро. Друг пропонує їй великий синій торт.'::text),
(306924,34103,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Presupuesto: 40 euros. Un amigo le ... una gran tarta azul.'::text,'ofrece'::text,'ofrecer'::text,'ofreciendo'::text,'Presupuesto: 40 euros. Un amigo le ofrece una gran tarta azul.'::text),
(306923,34103,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Budget : 40 euros. Un ami lui ... un gros gâteau bleu.'::text,'propose'::text,'proposer'::text,'proposant'::text,'Budget : 40 euros. Un ami lui propose un gros gâteau bleu.'::text),
(306926,34103,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütçe: 40 euro. Bir arkadaşı ona büyük mavi bir pasta ...'::text,'ikram eder'::text,'ikram etmek'::text,'ikram ederek'::text,'Bütçe: 40 euro. Bir arkadaşı ona büyük mavi bir pasta ikram eder.'::text),
(306927,34103,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Költségvetés: 40 euró. Egy barát egy nagy kék tortát ... neki.'::text,'kínál'::text,'kínálni'::text,'kínáló'::text,'Költségvetés: 40 euró. Egy barát egy nagy kék tortát kínál neki.'::text),
(306939,34105,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... bieten sie ihr an? Eine Torte mit 100 Kerzen! Unglaublich!'::text,'Was'::text,'Wer'::text,'Wo'::text,'Was bieten sie ihr an? Eine Torte mit 100 Kerzen! Unglaublich!'::text),
(306943,34105,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... їй пропонують? Торт зі 100 свічками! Неймовірно!'::text,'Що'::text,'Хто'::text,'Де'::text,'Що їй пропонують? Торт зі 100 свічками! Неймовірно!'::text),
(306942,34105,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... le ofrecen? ¡Una tarta con 100 velas! ¡Increíble!'::text,'Qué'::text,'Quién'::text,'Dónde'::text,'¿Qué le ofrecen? ¡Una tarta con 100 velas! ¡Increíble!'::text),
(306941,34105,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... lui offrent-ils ? Un gâteau avec 100 bougies ! Incroyable !'::text,'Que'::text,'Qui'::text,'Où'::text,'Que lui offrent-ils ? Un gâteau avec 100 bougies ! Incroyable !'::text),
(306944,34105,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ona ... ikram ediyorlar? 100 mumlu bir pasta! İnanılmaz!'::text,'ne'::text,'kim'::text,'nerede'::text,'Ona ne ikram ediyorlar? 100 mumlu bir pasta! İnanılmaz!'::text),
(306945,34105,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... kínálnak neki? Egy tortát 100 gyertyával! Hihetetlen!'::text,'Mit'::text,'Ki'::text,'Hol'::text,'Mit kínálnak neki? Egy tortát 100 gyertyával! Hihetetlen!'::text),
(306948,34106,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Letzten Sonntag ... ihr ein Freund eine türkise Torte mit Kerzen an.'::text,'bot'::text,'bietet'::text,'anbietend'::text,'Letzten Sonntag bot ihr ein Freund eine türkise Torte mit Kerzen an.'::text),
(306952,34106,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Минулої неділі друг ... їй бірюзовий торт зі свічками.'::text,'запропонував'::text,'пропонує'::text,'пропонуючи'::text,'Минулої неділі друг запропонував їй бірюзовий торт зі свічками.'::text),
(306951,34106,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El domingo pasado, un amigo le ... una tarta turquesa con velas.'::text,'ofreció'::text,'ofrece'::text,'ofreciendo'::text,'El domingo pasado, un amigo le ofreció una tarta turquesa con velas.'::text),
(306950,34106,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dimanche dernier, un ami lui ... un gâteau turquoise avec des bougies.'::text,'a proposé'::text,'propose'::text,'proposant'::text,'Dimanche dernier, un ami lui a proposé un gâteau turquoise avec des bougies.'::text),
(306953,34106,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Geçen pazar bir arkadaşı ona mumlu turkuaz bir pasta ...'::text,'ikram etti'::text,'ikram eder'::text,'ikram ederek'::text,'Geçen pazar bir arkadaşı ona mumlu turkuaz bir pasta ikram etti.'::text),
(306954,34106,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Múlt vasárnap egy barát ... neki egy türkiz tortát gyertyákkal.'::text,'kínált'::text,'kínál'::text,'kínáló'::text,'Múlt vasárnap egy barát kínált neki egy türkiz tortát gyertyákkal.'::text),
(306957,34107,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sonst bieten sie ihr Tee an, aber gestern ... sie ihr eine Torte an.'::text,'boten'::text,'bieten'::text,NULL::text,'Sonst bieten sie ihr Tee an, aber gestern boten sie ihr eine Torte an.'::text),
(306961,34107,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай вони пропонують їй чай, але вчора ... їй торт.'::text,'запропонували'::text,'пропонують'::text,NULL::text,'Зазвичай вони пропонують їй чай, але вчора запропонували їй торт.'::text),
(306960,34107,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente le ofrecen té, pero ayer le ... una tarta.'::text,'ofrecieron'::text,'ofrecen'::text,NULL::text,'Normalmente le ofrecen té, pero ayer le ofrecieron una tarta.'::text),
(306959,34107,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude, ils lui proposent du thé, mais hier ils lui ... un gâteau.'::text,'ont proposé'::text,'proposent'::text,NULL::text,'D''habitude, ils lui proposent du thé, mais hier ils lui ont proposé un gâteau.'::text),
(306962,34107,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde ona çay ikram ederler ama dün ona pasta ...'::text,'ikram ettiler'::text,'ikram ederler'::text,NULL::text,'Genelde ona çay ikram ederler ama dün ona pasta ikram ettiler.'::text),
(306963,34107,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában teát kínálnak neki, de tegnap tortát ...'::text,'kínáltak'::text,'kínálnak'::text,NULL::text,'Általában teát kínálnak neki, de tegnap tortát kínáltak.'::text),
(306966,34108,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Makellose Partyregeln, klar: Der Gastgeber ... die Torte anbieten und sie dann wegstellen.'::text,'muss'::text,'muss'::text,'sollte'::text,'Makellose Partyregeln, klar: Der Gastgeber muss die Torte anbieten und sie dann wegstellen.'::text),
(306970,34108,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бездоганні правила вечірки, авжеж: господар ... запропонувати торт, а потім забрати його.'::text,'має'::text,'мусить'::text,'мав би'::text,'Бездоганні правила вечірки, авжеж: господар має запропонувати торт, а потім забрати його.'::text),
(306969,34108,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Reglas de fiesta impecables, claro: el anfitrión ... ofrecer la tarta y luego moverla.'::text,'tiene que'::text,'debe'::text,'debería'::text,'Reglas de fiesta impecables, claro: el anfitrión tiene que ofrecer la tarta y luego moverla.'::text),
(306968,34108,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Des règles de fête parfaites, évidemment : l''hôte ... proposer le gâteau, puis le déplacer.'::text,'doit'::text,'doit'::text,'devrait'::text,'Des règles de fête parfaites, évidemment : l''hôte doit proposer le gâteau, puis le déplacer.'::text),
(306971,34108,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kusursuz parti kuralları, belli ki: ev sahibi pastayı ikram edip sonra kenara ...'::text,'çekmek zorunda'::text,'çekmeli'::text,'çekmeli'::text,'Kusursuz parti kuralları, belli ki: ev sahibi pastayı ikram edip sonra kenara çekmek zorunda.'::text),
(306972,34108,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hibátlan bulis szabályok, nyilván: a házigazdának ... felkínálnia a tortát, aztán elvinnie.'::text,'kell'::text,'kell'::text,'kellene'::text,'Hibátlan bulis szabályok, nyilván: a házigazdának kell felkínálnia a tortát, aztán elvinnie.'::text),
(306984,34110,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, sie lacht lowkey, ... sie ihr eine Torte mit 100 Kerzen anbieten.'::text,'weil'::text,'aber'::text,'also'::text,'Alter, sie lacht lowkey, weil sie ihr eine Torte mit 100 Kerzen anbieten.'::text),
(306988,34110,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона тихенько сміється, ... їй пропонують торт зі 100 свічками.'::text,'бо'::text,'але'::text,'тому'::text,'Бро, вона тихенько сміється, бо їй пропонують торт зі 100 свічками.'::text),
(306987,34110,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, se está riendo un poco ... le ofrecen una tarta con 100 velas.'::text,'porque'::text,'pero'::text,'así que'::text,'Tío, se está riendo un poco porque le ofrecen una tarta con 100 velas.'::text),
(306986,34110,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, elle rigole un peu ... on lui offre un gâteau à 100 bougies.'::text,'parce qu'''::text,'mais'::text,'donc'::text,'Frère, elle rigole un peu parce qu'' on lui offre un gâteau à 100 bougies.'::text),
(306989,34110,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, biraz gülüyor ... ona 100 mumlu bir pasta ikram ediyorlar.'::text,'çünkü'::text,'ama'::text,'bu yüzden'::text,'Kanka, biraz gülüyor çünkü ona 100 mumlu bir pasta ikram ediyorlar.'::text),
(306990,34110,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, kicsit nevet, ... egy 100 gyertyás tortát kínálnak neki.'::text,'mert'::text,'de'::text,'ezért'::text,'Tesó, kicsit nevet, mert egy 100 gyertyás tortát kínálnak neki.'::text),
(307848,34206,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Albtraum! Er ... den ganzen Rasen lila für Oma an!'::text,'malt'::text,'malt'::text,'malt'::text,'Albtraum! Er malt den ganzen Rasen lila für Oma an!'::text),
(307852,34206,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жах! Він ... весь газон у фіолетовий для бабусі!'::text,'фарбує'::text,'фарбує'::text,'фарбує'::text,'Жах! Він фарбує весь газон у фіолетовий для бабусі!'::text),
(307851,34206,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Pesadilla! ¡... todo el césped de morado para la abuela!'::text,'Está pintando'::text,'Pinta'::text,'Está pintando'::text,'¡Pesadilla! ¡Está pintando todo el césped de morado para la abuela!'::text),
(307850,34206,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cauchemar ! Il ... toute la pelouse en violet pour mamie !'::text,'est en train de peindre'::text,'peint'::text,'est en train de peindre'::text,'Cauchemar ! Il est en train de peindre toute la pelouse en violet pour mamie !'::text),
(307853,34206,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâbus! Büyükannesi için bütün çimi mora ...!'::text,'boyuyor'::text,'boyar'::text,'boyuyor'::text,'Kâbus! Büyükannesi için bütün çimi mora boyuyor!'::text),
(307854,34206,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rémálom! Az egész gyepet lilára ... a nagyinak!'::text,'festi'::text,'festi'::text,'festi'::text,'Rémálom! Az egész gyepet lilára festi a nagyinak!'::text),
(307857,34207,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er malt nie, aber heute ... er den ganzen Rasen an! Chaos!'::text,'malt'::text,'malt'::text,NULL::text,'Er malt nie, aber heute malt er den ganzen Rasen an! Chaos!'::text),
(307861,34207,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ніколи не малює, але сьогодні ... весь газон! Хаос!'::text,'фарбує'::text,'фарбує'::text,NULL::text,'Він ніколи не малює, але сьогодні фарбує весь газон! Хаос!'::text),
(307860,34207,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nunca pinta, ¡pero hoy ... todo el césped! ¡Caos!'::text,'está pintando'::text,'pinta'::text,NULL::text,'Nunca pinta, ¡pero hoy está pintando todo el césped! ¡Caos!'::text),
(307859,34207,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ne peint jamais, mais aujourd''hui il ... toute la pelouse ! Chaos !'::text,'est en train de peindre'::text,'peint'::text,NULL::text,'Il ne peint jamais, mais aujourd''hui il est en train de peindre toute la pelouse ! Chaos !'::text),
(307862,34207,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hiç resim yapmaz ama bugün bütün çimi ...! Kaos!'::text,'boyuyor'::text,'boyar'::text,NULL::text,'Hiç resim yapmaz ama bugün bütün çimi boyuyor! Kaos!'::text),
(307863,34207,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Soha nem fest, de ma az egész gyepet ...! Káosz!'::text,'festi'::text,'festi'::text,NULL::text,'Soha nem fest, de ma az egész gyepet festi! Káosz!'::text),
(307866,34208,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn es Oma gefällt, ... er den Rasen nächstes Jahr wieder bemalen.'::text,'wird'::text,'bemalt'::text,'bemalte'::text,'Wenn es Oma gefällt, wird er den Rasen nächstes Jahr wieder bemalen.'::text),
(307870,34208,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо бабусі сподобається, він ... газон знову наступного року.'::text,'пофарбує'::text,'фарбує'::text,'фарбував'::text,'Якщо бабусі сподобається, він пофарбує газон знову наступного року.'::text),
(307869,34208,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si a la abuela le gusta, ... el césped otra vez el año que viene.'::text,'pintará'::text,'pinta'::text,'pintó'::text,'Si a la abuela le gusta, pintará el césped otra vez el año que viene.'::text),
(307868,34208,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ça plaît à mamie, il ... encore la pelouse l''année prochaine.'::text,'peindra'::text,'peint'::text,'a peint'::text,'Si ça plaît à mamie, il peindra encore la pelouse l''année prochaine.'::text),
(307871,34208,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Büyükannesi beğenirse, seneye çimi yine ...'::text,'boyayacak'::text,'boyar'::text,'boyadı'::text,'Büyükannesi beğenirse, seneye çimi yine boyayacak.'::text),
(307872,34208,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a nagyinak tetszik, jövőre újra ... a gyepet.'::text,'ki fogja festeni'::text,'kifesti'::text,'kifestette'::text,'Ha a nagyinak tetszik, jövőre újra ki fogja festeni a gyepet.'::text),
(307884,34210,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, der Schlauch läuft schon, er ... den ganzen Rasen bemalen, echt.'::text,'wird'::text,'wird'::text,NULL::text,'Yo, der Schlauch läuft schon, er wird den ganzen Rasen bemalen, echt.'::text),
(307888,34210,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, шланг уже працює, він ... весь газон, реально.'::text,'збирається пофарбувати'::text,'пофарбує'::text,NULL::text,'Йо, шланг уже працює, він збирається пофарбувати весь газон, реально.'::text),
(307887,34210,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ey, la manguera ya está en marcha, ... todo el césped, en serio.'::text,'va a pintar'::text,'pintará'::text,NULL::text,'Ey, la manguera ya está en marcha, va a pintar todo el césped, en serio.'::text),
(307886,34210,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, le tuyau est déjà ouvert, il ... toute la pelouse, sérieux.'::text,'va peindre'::text,'peindra'::text,NULL::text,'Yo, le tuyau est déjà ouvert, il va peindre toute la pelouse, sérieux.'::text),
(307889,34210,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, hortum zaten açık, bütün çimi ..., cidden.'::text,'boyayacak'::text,'boyayacak'::text,NULL::text,'Kanka, hortum zaten açık, bütün çimi boyayacak, cidden.'::text),
(307890,34210,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, a slag már megy, az egész gyepet ..., komolyan.'::text,'ki fogja festeni'::text,'ki fogja festeni'::text,NULL::text,'Figyu, a slag már megy, az egész gyepet ki fogja festeni, komolyan.'::text),
(307893,34211,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, das ist echt seine eigene Idee: Er ... den ganzen Rasen bemalen.'::text,'muss'::text,'muss'::text,'sollte'::text,'Alter, das ist echt seine eigene Idee: Er muss den ganzen Rasen bemalen.'::text),
(307897,34211,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, це реально його власна ідея: він ... пофарбувати весь газон.'::text,'мусить'::text,'має'::text,'мав би'::text,'Бро, це реально його власна ідея: він мусить пофарбувати весь газон.'::text),
(307896,34211,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, es idea suya, en serio: ... pintar todo el césped.'::text,'debe'::text,'tiene que'::text,'debería'::text,'Tío, es idea suya, en serio: debe pintar todo el césped.'::text),
(307895,34211,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, c''est son idée à lui, sérieux : il ... peindre toute la pelouse.'::text,'doit'::text,'doit'::text,'devrait'::text,'Frère, c''est son idée à lui, sérieux : il doit peindre toute la pelouse.'::text),
(307898,34211,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu cidden onun kendi fikri: bütün çimi ...'::text,'boyamalı'::text,'boyamak zorunda'::text,'boyamalı'::text,'Kanka, bu cidden onun kendi fikri: bütün çimi boyamalı.'::text),
(307899,34211,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ez tényleg az ő ötlete: az egész gyepet ki ... festenie.'::text,'kell'::text,'kell'::text,'kellene'::text,'Tesó, ez tényleg az ő ötlete: az egész gyepet ki kell festenie.'::text),
(307902,34212,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deadline: 15 Uhr. Er ... den Rasen bemalen, bevor Oma kommt.'::text,'sollte'::text,'sollte'::text,'sollte'::text,'Deadline: 15 Uhr. Er sollte den Rasen bemalen, bevor Oma kommt.'::text),
(307906,34212,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дедлайн: 15:00. Він ... пофарбувати газон до приїзду бабусі.'::text,'мав би'::text,'мав би'::text,'мав би'::text,'Дедлайн: 15:00. Він мав би пофарбувати газон до приїзду бабусі.'::text),
(307905,34212,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plazo: las 15:00. ... pintar el césped antes de que llegue la abuela.'::text,'Debería'::text,'Debería'::text,'Debería'::text,'Plazo: las 15:00. Debería pintar el césped antes de que llegue la abuela.'::text),
(307904,34212,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deadline : 15 h. Il ... peindre la pelouse avant l''arrivée de mamie.'::text,'devrait'::text,'devrait'::text,'devrait'::text,'Deadline : 15 h. Il devrait peindre la pelouse avant l''arrivée de mamie.'::text),
(307907,34212,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son tarih: 15:00. Büyükannesi gelmeden çimi ...'::text,'boyamalı'::text,'boyamalı'::text,'boyamalı'::text,'Son tarih: 15:00. Büyükannesi gelmeden çimi boyamalı.'::text),
(307908,34212,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Határidő: 15 óra. Ki ... festenie a gyepet, mielőtt a nagyi megérkezik.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'Határidő: 15 óra. Ki kellene festenie a gyepet, mielőtt a nagyi megérkezik.'::text),
(307911,34213,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er bemalt den Rasen, ... der Rasen das große grüne Ding da ist.'::text,'weil'::text,'aber'::text,'also'::text,'Er bemalt den Rasen, weil der Rasen das große grüne Ding da ist.'::text),
(307915,34213,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він фарбує газон, ... газон — це та велика зелена штука там.'::text,'бо'::text,'але'::text,'тому'::text,'Він фарбує газон, бо газон — це та велика зелена штука там.'::text),
(307914,34213,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pinta el césped ... el césped es esa cosa verde grande de ahí.'::text,'porque'::text,'pero'::text,'así que'::text,'Pinta el césped porque el césped es esa cosa verde grande de ahí.'::text),
(307913,34213,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il peint la pelouse ... la pelouse, c''est le grand truc vert là-bas.'::text,'parce que'::text,'mais'::text,'donc'::text,'Il peint la pelouse parce que la pelouse, c''est le grand truc vert là-bas.'::text),
(307916,34213,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çimi boyuyor ... çim oradaki büyük yeşil şey.'::text,'çünkü'::text,'ama'::text,'bu yüzden'::text,'Çimi boyuyor çünkü çim oradaki büyük yeşil şey.'::text),
(307917,34213,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Festi a gyepet, ... a gyep az a nagy zöld dolog ott.'::text,'mert'::text,'de'::text,'ezért'::text,'Festi a gyepet, mert a gyep az a nagy zöld dolog ott.'::text),
(296760,32974,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Unglaublich! Oma ... ein Geschenk mit einem Mann drin!'::text,'hat'::text,'haben'::text,'hat'::text,'Unglaublich! Oma hat ein Geschenk mit einem Mann drin!'::text),
(296764,32974,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Неймовірно! Бабуся ... подарунок із чоловіком усередині!'::text,'має'::text,'мати'::text,'має'::text,'Неймовірно! Бабуся має подарунок із чоловіком усередині!'::text),
(296763,32974,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Increíble! ¡La abuela ... un regalo con un hombre dentro!'::text,'tiene'::text,'tienen'::text,'tiene'::text,'¡Increíble! ¡La abuela tiene un regalo con un hombre dentro!'::text),
(296762,32974,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Incroyable ! Mamie ... un cadeau avec un homme dedans !'::text,'a'::text,'ont'::text,'a'::text,'Incroyable ! Mamie a un cadeau avec un homme dedans !'::text),
(296765,32974,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İnanılmaz! Büyükannenin içinde adam olan bir hediyesi ...!'::text,'var'::text,'var'::text,'var'::text,'İnanılmaz! Büyükannenin içinde adam olan bir hediyesi var!'::text),
(296766,32974,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hihetetlen! A nagyinak ... egy ajándéka, benne egy férfival!'::text,'van'::text,'van'::text,'van'::text,'Hihetetlen! A nagyinak van egy ajándéka, benne egy férfival!'::text),
(296769,32975,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein Mann steigt aus dem Geschenk mit roten herzförmigen ...'::text,'Ballons.'::text,'Ballon.'::text,'Ballons.'::text,'Ein Mann steigt aus dem Geschenk mit roten herzförmigen Ballons.'::text),
(296773,32975,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'З подарунка виходить чоловік із червоними серцеподібними ...'::text,'кульками.'::text,'кулькою.'::text,'кульками.'::text,'З подарунка виходить чоловік із червоними серцеподібними кульками.'::text),
(296772,32975,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un hombre sale del regalo con ... rojos en forma de corazón.'::text,'globos'::text,'globo'::text,'globos'::text,'Un hombre sale del regalo con globos rojos en forma de corazón.'::text),
(296771,32975,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un homme sort du cadeau avec des ... rouges en forme de cœur.'::text,'ballons'::text,'ballon'::text,'ballons'::text,'Un homme sort du cadeau avec des ballons rouges en forme de cœur.'::text),
(296774,32975,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hediyeden kırmızı kalp ... ile bir adam çıkıyor.'::text,'balonlar'::text,'balon'::text,'balonlar'::text,'Hediyeden kırmızı kalp balonlar ile bir adam çıkıyor.'::text),
(296775,32975,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy férfi lép ki az ajándékból piros szív alakú ...'::text,'lufikkal.'::text,'lufival.'::text,'lufikkal.'::text,'Egy férfi lép ki az ajándékból piros szív alakú lufikkal.'::text),
(296778,32976,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oma sieht eine große Kiste. Sie öffnet ... Geschenkbox.'::text,'die'::text,'eine'::text,'eine'::text,'Oma sieht eine große Kiste. Sie öffnet die Geschenkbox.'::text),
(296782,32976,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бабуся бачить велику коробку. Вона відкриває ... подарункову коробку.'::text,''::text,NULL::text,NULL::text,'Бабуся бачить велику коробку. Вона відкриває подарункову коробку.'::text),
(296781,32976,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La abuela ve una caja grande. Abre ... caja de regalo.'::text,'la'::text,'una'::text,'una'::text,'La abuela ve una caja grande. Abre la caja de regalo.'::text),
(296780,32976,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mamie voit une grande boîte. Elle ouvre ... boîte cadeau.'::text,'la'::text,'une'::text,'une'::text,'Mamie voit une grande boîte. Elle ouvre la boîte cadeau.'::text),
(296783,32976,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Büyükanne büyük bir kutu görüyor. ... hediye kutusunu açıyor.'::text,''::text,'bir'::text,'bir'::text,'Büyükanne büyük bir kutu görüyor. Hediye kutusunu açıyor.'::text),
(296784,32976,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nagyi egy nagy dobozt lát. Kinyitja ... ajándékdobozt.'::text,'az'::text,'egy'::text,'egy'::text,'A nagyi egy nagy dobozt lát. Kinyitja az ajándékdobozt.'::text),
(296796,32978,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bericht: Das Geschenk ist 2 Meter hoch. Oma öffnet ... Vorderwand.'::text,'seine'::text,'ihre'::text,'ihre'::text,'Bericht: Das Geschenk ist 2 Meter hoch. Oma öffnet seine Vorderwand.'::text),
(296800,32978,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звіт: подарунок заввишки 2 метри. Бабуся відкриває ... передню стінку.'::text,'його'::text,'свою'::text,'їхню'::text,'Звіт: подарунок заввишки 2 метри. Бабуся відкриває його передню стінку.'::text),
(296799,32978,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Informe: el regalo mide 2 metros. La abuela abre ... panel frontal.'::text,'su'::text,'su'::text,'su'::text,'Informe: el regalo mide 2 metros. La abuela abre su panel frontal.'::text),
(296798,32978,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rapport : le cadeau fait 2 mètres de haut. Mamie ouvre ... panneau avant.'::text,'son'::text,'son'::text,'leur'::text,'Rapport : le cadeau fait 2 mètres de haut. Mamie ouvre son panneau avant.'::text),
(296801,32978,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rapor: hediye 2 metre boyunda. Büyükanne ... ön panelini açıyor.'::text,'onun'::text,'onun'::text,'onların'::text,'Rapor: hediye 2 metre boyunda. Büyükanne onun ön panelini açıyor.'::text),
(296802,32978,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jelentés: az ajándék 2 méter magas. A nagyi kinyitja az ...'::text,'előlapját'::text,'előlapját'::text,'előlapjukat'::text,'Jelentés: az ajándék 2 méter magas. A nagyi kinyitja az előlapját.'::text),
(296805,32979,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann ist ... der Geschenkbox, weil er drin ist.'::text,'in'::text,'auf'::text,'an'::text,'Der Mann ist in der Geschenkbox, weil er drin ist.'::text),
(296809,32979,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік ... подарунковій коробці, бо він усередині неї.'::text,'у'::text,'на'::text,'біля'::text,'Чоловік у подарунковій коробці, бо він усередині неї.'::text),
(296808,32979,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre está ... la caja de regalo porque está dentro.'::text,'en'::text,'sobre'::text,'a'::text,'El hombre está en la caja de regalo porque está dentro.'::text),
(296807,32979,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme est ... la boîte cadeau parce qu''il est dedans.'::text,'dans'::text,'sur'::text,'à'::text,'L''homme est dans la boîte cadeau parce qu''il est dedans.'::text),
(296810,32979,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam hediye kutusunun ..., çünkü onun içinde.'::text,'içinde'::text,'üstünde'::text,NULL::text,'Adam hediye kutusunun içinde, çünkü onun içinde.'::text),
(296811,32979,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi az ... van, mert benne van.'::text,'ajándékdobozban'::text,'ajándékdobozon'::text,'ajándékdoboznál'::text,'A férfi az ajándékdobozban van, mert benne van.'::text),
(296823,32981,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Absolut unglaublich! Da ... ein ganzer Mann im Geschenk!'::text,'ist'::text,'sind'::text,'sein'::text,'Absolut unglaublich! Da ist ein ganzer Mann im Geschenk!'::text),
(296827,32981,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Просто неймовірно! У подарунку ... цілий чоловік!'::text,'є'::text,'є'::text,'бути'::text,'Просто неймовірно! У подарунку є цілий чоловік!'::text),
(296826,32981,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Absolutamente increíble! ¡... un hombre entero dentro del regalo!'::text,'Hay'::text,'Hay'::text,'Hay'::text,'¡Absolutamente increíble! ¡Hay un hombre entero dentro del regalo!'::text),
(296825,32981,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Absolument incroyable ! ... un homme entier dans le cadeau !'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Absolument incroyable ! Il y a un homme entier dans le cadeau !'::text),
(296828,32981,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kesinlikle inanılmaz! Hediyenin içinde koca bir adam ...!'::text,'var'::text,'var'::text,'olmak'::text,'Kesinlikle inanılmaz! Hediyenin içinde koca bir adam var!'::text),
(296829,32981,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Teljesen hihetetlen! Egy egész férfi ... az ajándékban!'::text,'van'::text,'vannak'::text,'lenni'::text,'Teljesen hihetetlen! Egy egész férfi van az ajándékban!'::text),
(312843,34761,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt, dein Hund ... normalerweise jeden Ball zurück. Respekt.'::text,'bringt'::text,'brachte'::text,NULL::text,'Ehrlich gesagt, dein Hund bringt normalerweise jeden Ball zurück. Respekt.'::text),
(312847,34761,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не збрешу, твій пес зазвичай ... кожен м''яч. Респект.'::text,'повертає'::text,'повернув'::text,NULL::text,'Не збрешу, твій пес зазвичай повертає кожен м''яч. Респект.'::text),
(312846,34761,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No te voy a mentir, tu perro normalmente ... todas las pelotas. Respeto.'::text,'devuelve'::text,'devolvió'::text,NULL::text,'No te voy a mentir, tu perro normalmente devuelve todas las pelotas. Respeto.'::text),
(312845,34761,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, ton chien ... toutes les balles d''habitude. Respect.'::text,'rapporte'::text,'a rapporté'::text,NULL::text,'Je vais pas mentir, ton chien rapporte toutes les balles d''habitude. Respect.'::text),
(312848,34761,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, köpeğin her topu genelde geri ..., helal olsun.'::text,'getirir'::text,'getirdi'::text,NULL::text,'Yalan yok, köpeğin her topu genelde geri getirir, helal olsun.'::text),
(312849,34761,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem fogok hazudni, a kutyád általában ... minden labdát. Respekt.'::text,'visszahoz'::text,'visszahozott'::text,NULL::text,'Nem fogok hazudni, a kutyád általában visszahoz minden labdát. Respekt.'::text),
(312852,34762,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eindeutig ein fauler Hund: Er ... gerade zur Maschine zurück.'::text,'kehrt'::text,'kehrt'::text,'kehrt'::text,'Eindeutig ein fauler Hund: Er kehrt gerade zur Maschine zurück.'::text),
(312856,34762,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Явно лінивий пес: саме зараз він ... до автомата.'::text,'повертається'::text,'повертається'::text,'повертається'::text,'Явно лінивий пес: саме зараз він повертається до автомата.'::text),
(312855,34762,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Claramente un perro vago: ahora mismo ... a la máquina.'::text,'está volviendo'::text,'vuelve'::text,'está volviendo'::text,'Claramente un perro vago: ahora mismo está volviendo a la máquina.'::text),
(312854,34762,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Clairement un chien paresseux : il ... vers la machine en ce moment.'::text,'est en train de revenir'::text,'revient'::text,'est en train de revenir'::text,'Clairement un chien paresseux : il est en train de revenir vers la machine en ce moment.'::text),
(312857,34762,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki tembel bir köpek: şu an makineye ...'::text,'dönüyor'::text,'döner'::text,'dönüyor'::text,'Belli ki tembel bir köpek: şu an makineye dönüyor.'::text),
(312858,34762,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilvánvalóan lusta kutya: épp most ... vissza a géphez.'::text,'megy'::text,'megy'::text,'megy'::text,'Nyilvánvalóan lusta kutya: épp most megy vissza a géphez.'::text),
(312861,34763,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein echter Profi: Der Hund schläft sonst, aber heute ... er jeden Ball zurück.'::text,'bringt'::text,'bringt'::text,NULL::text,'Ein echter Profi: Der Hund schläft sonst, aber heute bringt er jeden Ball zurück.'::text),
(312865,34763,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Справжній профі: пес зазвичай спить, але сьогодні він ... кожен м''яч.'::text,'повертає'::text,'повертає'::text,NULL::text,'Справжній профі: пес зазвичай спить, але сьогодні він повертає кожен м''яч.'::text),
(312864,34763,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Todo un profesional: el perro normalmente duerme, pero hoy ... todas las pelotas.'::text,'está devolviendo'::text,'devuelve'::text,NULL::text,'Todo un profesional: el perro normalmente duerme, pero hoy está devolviendo todas las pelotas.'::text),
(312863,34763,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un vrai pro : d''habitude, le chien dort, mais aujourd''hui il ... toutes les balles.'::text,'est en train de rapporter'::text,'rapporte'::text,NULL::text,'Un vrai pro : d''habitude, le chien dort, mais aujourd''hui il est en train de rapporter toutes les balles.'::text),
(312866,34763,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tam bir profesyonel: köpek genelde uyur ama bugün her topu geri ...'::text,'getiriyor'::text,'getirir'::text,NULL::text,'Tam bir profesyonel: köpek genelde uyur ama bugün her topu geri getiriyor.'::text),
(312867,34763,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Igazi profi: a kutya általában alszik, de ma ... minden labdát.'::text,'visszahozza'::text,'visszahozza'::text,NULL::text,'Igazi profi: a kutya általában alszik, de ma visszahozza minden labdát.'::text),
(312870,34764,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich bin sicher, der Hund ... auch den nächsten Ball zurückbringen. Makellos, klar.'::text,'wird'::text,'bringt'::text,'brachte'::text,'Ich bin sicher, der Hund wird auch den nächsten Ball zurückbringen. Makellos, klar.'::text),
(312874,34764,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Я впевнений, що пес ... і наступний м''яч. Бездоганно, авжеж.'::text,'поверне'::text,'повертає'::text,'повернув'::text,'Я впевнений, що пес поверне і наступний м''яч. Бездоганно, авжеж.'::text),
(312873,34764,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Estoy seguro de que el perro ... también la siguiente pelota. Impecable, claro.'::text,'devolverá'::text,'devuelve'::text,'devolvió'::text,'Estoy seguro de que el perro devolverá también la siguiente pelota. Impecable, claro.'::text),
(312872,34764,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je suis sûr que le chien ... aussi la prochaine balle. Parfait, évidemment.'::text,'rapportera'::text,'rapporte'::text,'a rapporté'::text,'Je suis sûr que le chien rapportera aussi la prochaine balle. Parfait, évidemment.'::text),
(312875,34764,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eminim köpek bir sonraki topu da geri ...; kusursuz, belli ki.'::text,'getirecek'::text,'getirir'::text,'getirdi'::text,'Eminim köpek bir sonraki topu da geri getirecek; kusursuz, belli ki.'::text),
(312876,34764,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Biztos vagyok benne, hogy a kutya ... a következő labdát is. Hibátlan, nyilván.'::text,'vissza fogja hozni'::text,'visszahozza'::text,'visszahozta'::text,'Biztos vagyok benne, hogy a kutya vissza fogja hozni a következő labdát is. Hibátlan, nyilván.'::text),
(312879,34765,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Ball ist in seinem Maul, also ... er zur Maschine zurückkehren.'::text,'wird'::text,'wird'::text,'kehrt'::text,'Der Ball ist in seinem Maul, also wird er zur Maschine zurückkehren.'::text),
(312883,34765,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'М''яч у нього в пащі, тож він ... до автомата.'::text,'збирається повернутися'::text,'повернеться'::text,'повертається'::text,'М''яч у нього в пащі, тож він збирається повернутися до автомата.'::text),
(312882,34765,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tiene la pelota en la boca, así que ... a la máquina.'::text,'va a volver'::text,'volverá'::text,'vuelve'::text,'Tiene la pelota en la boca, así que va a volver a la máquina.'::text),
(312881,34765,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La balle est dans sa gueule, donc il ... à la machine.'::text,'va retourner'::text,'retournera'::text,'retourne'::text,'La balle est dans sa gueule, donc il va retourner à la machine.'::text),
(312884,34765,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Top ağzında, bu yüzden makineye ...'::text,'dönecek'::text,'dönecek'::text,'döner'::text,'Top ağzında, bu yüzden makineye dönecek.'::text),
(312885,34765,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A labda a szájában van, szóval ... a géphez.'::text,'vissza fog menni'::text,'vissza fog menni'::text,'visszamegy'::text,'A labda a szájában van, szóval vissza fog menni a géphez.'::text),
(312888,34766,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich glaube, der Hund ... heute jeden Ball zurückbringen.'::text,'wird'::text,'wird'::text,NULL::text,'Ich glaube, der Hund wird heute jeden Ball zurückbringen.'::text),
(312892,34766,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Думаю, пес сьогодні ... кожен м''яч.'::text,'поверне'::text,'збирається повернути'::text,NULL::text,'Думаю, пес сьогодні поверне кожен м''яч.'::text),
(312891,34766,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Creo que el perro hoy ... todas las pelotas.'::text,'devolverá'::text,'va a devolver'::text,NULL::text,'Creo que el perro hoy devolverá todas las pelotas.'::text),
(312890,34766,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je pense que le chien ... toutes les balles aujourd''hui.'::text,'rapportera'::text,'va rapporter'::text,NULL::text,'Je pense que le chien rapportera toutes les balles aujourd''hui.'::text),
(312893,34766,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bence köpek bugün her topu geri ...'::text,'getirecek'::text,'getirecek'::text,NULL::text,'Bence köpek bugün her topu geri getirecek.'::text),
(312894,34766,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szerintem a kutya ma minden labdát vissza ... hozni.'::text,'fog'::text,'fog'::text,NULL::text,'Szerintem a kutya ma minden labdát vissza fog hozni.'::text),
(305040,33894,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Katze und der Löwe ... sich an den schwarzen Gitterstäben.'::text,'treffen'::text,'trifft'::text,'treffend'::text,'Die Katze und der Löwe treffen sich an den schwarzen Gitterstäben.'::text),
(305044,33894,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кіт і лев ... біля чорних ґрат.'::text,'зустрічаються'::text,'зустрічається'::text,'зустрічаючись'::text,'Кіт і лев зустрічаються біля чорних ґрат.'::text),
(305043,33894,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El gato y el león ... junto a los barrotes negros.'::text,'se encuentran'::text,'se encuentra'::text,'encontrándose'::text,'El gato y el león se encuentran junto a los barrotes negros.'::text),
(305042,33894,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chat et le lion ... près des barreaux noirs.'::text,'se rencontrent'::text,'se rencontre'::text,'se rencontrant'::text,'Le chat et le lion se rencontrent près des barreaux noirs.'::text),
(305045,33894,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kedi ve aslan siyah parmaklıkların yanında ...'::text,'buluşurlar'::text,'buluşur'::text,'buluşarak'::text,'Kedi ve aslan siyah parmaklıkların yanında buluşurlar.'::text),
(305046,33894,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A macska és az oroszlán a fekete rácsnál ...'::text,'találkoznak'::text,'találkozik'::text,'találkozó'::text,'A macska és az oroszlán a fekete rácsnál találkoznak.'::text),
(305049,33895,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Katze ... den Löwen treffen, aber nur durch die Gitter.'::text,'kann'::text,'kann'::text,'kann'::text,'Die Katze kann den Löwen treffen, aber nur durch die Gitter.'::text),
(305053,33895,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кіт ... зустрітися з левом, але тільки крізь ґрати.'::text,'може'::text,'може'::text,'може'::text,'Кіт може зустрітися з левом, але тільки крізь ґрати.'::text),
(305052,33895,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El gato ... encontrarse con el león, pero solo a través de los barrotes.'::text,'puede'::text,'puede'::text,'puede'::text,'El gato puede encontrarse con el león, pero solo a través de los barrotes.'::text),
(305051,33895,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chat ... rencontrer le lion, mais seulement à travers les barreaux.'::text,'peut'::text,'peut'::text,'peut'::text,'Le chat peut rencontrer le lion, mais seulement à travers les barreaux.'::text),
(305054,33895,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kedi aslanla ..., ama sadece parmaklıkların arasından.'::text,'buluşabilir'::text,'buluşabilir'::text,'buluşabilir'::text,'Kedi aslanla buluşabilir, ama sadece parmaklıkların arasından.'::text),
(305055,33895,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A macska ... az oroszlánnal, de csak a rácson keresztül.'::text,'találkozhat'::text,'találkozhat'::text,'találkozhat'::text,'A macska találkozhat az oroszlánnal, de csak a rácson keresztül.'::text),
(305067,33897,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Letzte Woche ... die Katze einen Löwen im Zoo.'::text,'traf'::text,'trifft'::text,'traf'::text,'Letzte Woche traf die Katze einen Löwen im Zoo.'::text),
(305071,33897,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Минулого тижня кіт ... лева в зоопарку.'::text,'зустрів'::text,'зустрічає'::text,'зустрів'::text,'Минулого тижня кіт зустрів лева в зоопарку.'::text),
(305070,33897,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La semana pasada, el gato ... un león en el zoo.'::text,'se encontró con'::text,'se encuentra con'::text,'se encontró con'::text,'La semana pasada, el gato se encontró con un león en el zoo.'::text),
(305069,33897,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La semaine dernière, le chat ... un lion au zoo.'::text,'a rencontré'::text,'rencontre'::text,'a rencontré'::text,'La semaine dernière, le chat a rencontré un lion au zoo.'::text),
(305072,33897,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Geçen hafta kedi hayvanat bahçesinde bir aslanla ...'::text,'buluştu'::text,'buluşur'::text,'buluştu'::text,'Geçen hafta kedi hayvanat bahçesinde bir aslanla buluştu.'::text),
(305073,33897,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Múlt héten a macska ... egy oroszlánnal az állatkertben.'::text,'találkozott'::text,'találkozik'::text,'találkozott'::text,'Múlt héten a macska találkozott egy oroszlánnal az állatkertben.'::text),
(305076,33898,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Katze trifft sonst Vögel, aber gestern ... sie einen riesigen Löwen! Beängstigend!'::text,'traf'::text,'trifft'::text,NULL::text,'Die Katze trifft sonst Vögel, aber gestern traf sie einen riesigen Löwen! Beängstigend!'::text),
(305080,33898,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кіт зазвичай зустрічає птахів, але вчора він ... величезного лева! Страшно!'::text,'зустрів'::text,'зустрічає'::text,NULL::text,'Кіт зазвичай зустрічає птахів, але вчора він зустрів величезного лева! Страшно!'::text),
(305079,33898,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El gato normalmente se encuentra con pájaros, ¡pero ayer ... un león enorme! ¡Aterrador!'::text,'se encontró con'::text,'se encuentra con'::text,NULL::text,'El gato normalmente se encuentra con pájaros, ¡pero ayer se encontró con un león enorme! ¡Aterrador!'::text),
(305078,33898,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude le chat rencontre des oiseaux, mais hier il ... un lion énorme ! Terrifiant !'::text,'a rencontré'::text,'rencontre'::text,NULL::text,'D''habitude le chat rencontre des oiseaux, mais hier il a rencontré un lion énorme ! Terrifiant !'::text),
(305081,33898,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kedi genelde kuşlarla karşılaşır ama dün kocaman bir aslanla ...! Korkunç!'::text,'karşılaştı'::text,'karşılaşır'::text,NULL::text,'Kedi genelde kuşlarla karşılaşır ama dün kocaman bir aslanla karşılaştı! Korkunç!'::text),
(305082,33898,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A macska általában madarakkal találkozik, de tegnap egy hatalmas oroszlánnal ...! Rémisztő!'::text,'találkozott'::text,'találkozik'::text,NULL::text,'A macska általában madarakkal találkozik, de tegnap egy hatalmas oroszlánnal találkozott! Rémisztő!'::text),
(305094,33900,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katzen treffen sonst Katzen, aber heute ... sie einen Löwen, weil Löwen Katzen sind.'::text,'trifft'::text,'trifft'::text,NULL::text,'Katzen treffen sonst Katzen, aber heute trifft sie einen Löwen, weil Löwen Katzen sind.'::text),
(305098,33900,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коти зазвичай зустрічають котів, але сьогодні він ... лева, бо леви — це коти.'::text,'зустрічає'::text,'зустрічає'::text,NULL::text,'Коти зазвичай зустрічають котів, але сьогодні він зустрічає лева, бо леви — це коти.'::text),
(305097,33900,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los gatos normalmente se encuentran con gatos, pero hoy ... un león, porque los leones son gatos.'::text,'se está encontrando con'::text,'se encuentra con'::text,NULL::text,'Los gatos normalmente se encuentran con gatos, pero hoy se está encontrando con un león, porque los leones son gatos.'::text),
(305096,33900,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude les chats rencontrent des chats, mais aujourd''hui il ... un lion, parce que les lions sont des chats.'::text,'est en train de rencontrer'::text,'rencontre'::text,NULL::text,'D''habitude les chats rencontrent des chats, mais aujourd''hui il est en train de rencontrer un lion, parce que les lions sont des chats.'::text),
(305099,33900,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kediler genelde kedilerle karşılaşır ama bugün bir aslanla ..., çünkü aslanlar kedidir.'::text,'karşılaşıyor'::text,'karşılaşır'::text,NULL::text,'Kediler genelde kedilerle karşılaşır ama bugün bir aslanla karşılaşıyor, çünkü aslanlar kedidir.'::text),
(305100,33900,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A macskák általában macskákkal találkoznak, de ma egy oroszlánnal ..., mert az oroszlánok macskák.'::text,'találkozik'::text,'találkozik'::text,NULL::text,'A macskák általában macskákkal találkoznak, de ma egy oroszlánnal találkozik, mert az oroszlánok macskák.'::text),
(305103,33901,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, die Katze sagt angeblich, dass sie den Löwen morgen wieder ...'::text,'treffen wird'::text,'trifft'::text,'traf'::text,'Mädel, die Katze sagt angeblich, dass sie den Löwen morgen wieder treffen wird.'::text),
(305107,33901,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кіт нібито каже, що завтра знову ... лева.'::text,'зустріне'::text,'зустрічає'::text,'зустрів'::text,'Подруго, кіт нібито каже, що завтра знову зустріне лева.'::text),
(305106,33901,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, parece que el gato dice que mañana ... otra vez con el león.'::text,'se encontrará'::text,'se encuentra'::text,'se encontró'::text,'Tía, parece que el gato dice que mañana se encontrará otra vez con el león.'::text),
(305105,33901,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment le chat dit qu''il ... encore le lion demain.'::text,'rencontrera'::text,'rencontre'::text,'a rencontré'::text,'Ma belle, apparemment le chat dit qu''il rencontrera encore le lion demain.'::text),
(305108,33901,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre kedi diyor ki yarın aslanla yine ...'::text,'buluşacak'::text,'buluşur'::text,'buluştu'::text,'Kızım, duyduğuma göre kedi diyor ki yarın aslanla yine buluşacak.'::text),
(305109,33901,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag a macska azt mondja, hogy holnap újra ... az oroszlánnal.'::text,'találkozni fog'::text,'találkozik'::text,'találkozott'::text,'Csajszi, állítólag a macska azt mondja, hogy holnap újra találkozni fog az oroszlánnal.'::text),
(323976,35998,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Rakete ... über jeden Baum am Startplatz ragen.'::text,'kann'::text,'kann'::text,'ist'::text,'Die Rakete kann über jeden Baum am Startplatz ragen.'::text),
(323980,35998,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ракета ... височіти над кожним деревом на стартовому майданчику.'::text,'може'::text,'може'::text,'є'::text,'Ракета може височіти над кожним деревом на стартовому майданчику.'::text),
(323979,35998,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El cohete ... alzarse por encima de cada árbol de la plataforma de lanzamiento.'::text,'puede'::text,'puede'::text,'está'::text,'El cohete puede alzarse por encima de cada árbol de la plataforma de lanzamiento.'::text),
(323978,35998,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La fusée ... dominer chaque arbre du site de lancement.'::text,'peut'::text,'peut'::text,'est'::text,'La fusée peut dominer chaque arbre du site de lancement.'::text),
(323981,35998,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Roket fırlatma alanındaki her ağacın üstünde ...'::text,'yükselebilir'::text,'yükselebilir'::text,NULL::text,'Roket fırlatma alanındaki her ağacın üstünde yükselebilir.'::text),
(323982,35998,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A rakéta ... minden fa fölé az indítóhelyen.'::text,'magasodhat'::text,'magasodhat'::text,'van'::text,'A rakéta magasodhat minden fa fölé az indítóhelyen.'::text),
(323985,35999,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ragt die Rakete über ihm auf? Auf einem Startplatz.'::text,'Wo'::text,'Wer'::text,'Warum'::text,'Wo ragt die Rakete über ihm auf? Auf einem Startplatz.'::text),
(323989,35999,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... над ним височіє ракета? На стартовому майданчику.'::text,'Де'::text,'Хто'::text,'Чому'::text,'Де над ним височіє ракета? На стартовому майданчику.'::text),
(323988,35999,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... se alza el cohete sobre él? En una plataforma de lanzamiento.'::text,'Dónde'::text,'Quién'::text,'Por qué'::text,'¿Dónde se alza el cohete sobre él? En una plataforma de lanzamiento.'::text),
(323987,35999,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la fusée le domine-t-elle ? Sur un site de lancement.'::text,'Où'::text,'Qui'::text,'Pourquoi'::text,'Où la fusée le domine-t-elle ? Sur un site de lancement.'::text),
(323990,35999,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Roket onun üstünde ... yükseliyor? Bir fırlatma alanında.'::text,'nerede'::text,'kim'::text,'neden'::text,'Roket onun üstünde nerede yükseliyor? Bir fırlatma alanında.'::text),
(323991,35999,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... magasodik fölé a rakéta? Egy indítóhelyen.'::text,'Hol'::text,'Ki'::text,'Miért'::text,'Hol magasodik fölé a rakéta? Egy indítóhelyen.'::text),
(323994,36000,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine winzige Rakete, klar: Gestern ... sie über die Palmen.'::text,'ragte'::text,'ragt'::text,'ragen'::text,'Eine winzige Rakete, klar: Gestern ragte sie über die Palmen.'::text),
(323998,36000,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Крихітна ракета, авжеж: учора вона ... над пальмами.'::text,'височіла'::text,'височіє'::text,'височіти'::text,'Крихітна ракета, авжеж: учора вона височіла над пальмами.'::text),
(323997,36000,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un cohete diminuto, claro: ayer ... por encima de las palmeras.'::text,'se alzó'::text,'se alza'::text,'alzarse'::text,'Un cohete diminuto, claro: ayer se alzó por encima de las palmeras.'::text),
(323996,36000,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une fusée minuscule, évidemment : hier, elle ... les palmiers.'::text,'a dominé'::text,'domine'::text,'dominer'::text,'Une fusée minuscule, évidemment : hier, elle a dominé les palmiers.'::text),
(323999,36000,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minicik bir roket, belli ki: dün palmiyelerin üstünde ...'::text,'yükseldi'::text,'yükselir'::text,'yükselmek'::text,'Minicik bir roket, belli ki: dün palmiyelerin üstünde yükseldi.'::text),
(324000,36000,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Apró rakéta, nyilván: tegnap ... a pálmafák fölé.'::text,'magasodott'::text,'magasodik'::text,'magasodni'::text,'Apró rakéta, nyilván: tegnap magasodott a pálmafák fölé.'::text),
(324003,36001,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gestern ... die Rakete über ihm auf! Heute schreit er immer noch!'::text,'ragte'::text,'ragt'::text,NULL::text,'Gestern ragte die Rakete über ihm auf! Heute schreit er immer noch!'::text),
(324007,36001,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учора ракета ... над ним! Сьогодні він досі кричить!'::text,'височіла'::text,'височіє'::text,NULL::text,'Учора ракета височіла над ним! Сьогодні він досі кричить!'::text),
(324006,36001,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ayer el cohete ... sobre él! ¡Hoy todavía está gritando!'::text,'se alzó'::text,'se alza'::text,NULL::text,'¡Ayer el cohete se alzó sobre él! ¡Hoy todavía está gritando!'::text),
(324005,36001,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier, la fusée le ... ! Aujourd''hui, il hurle encore !'::text,'a dominé'::text,'domine'::text,NULL::text,'Hier, la fusée le a dominé ! Aujourd''hui, il hurle encore !'::text),
(324008,36001,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün roket onun üstünde ...! Bugün hâlâ çığlık atıyor!'::text,'yükseldi'::text,'yükselir'::text,NULL::text,'Dün roket onun üstünde yükseldi! Bugün hâlâ çığlık atıyor!'::text),
(324009,36001,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap a rakéta ... fölé! Ma még mindig sikít!'::text,'magasodott'::text,'magasodik'::text,NULL::text,'Tegnap a rakéta magasodott fölé! Ma még mindig sikít!'::text),
(324012,36002,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Rakete ragt über ihm auf! Er sagt: Ich ... springen, unbedingt!'::text,'muss'::text,'muss'::text,'muss nicht'::text,'Die Rakete ragt über ihm auf! Er sagt: Ich muss springen, unbedingt!'::text),
(324016,36002,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ракета височіє над ним! Він каже: я ... стрибати, однозначно!'::text,'мушу'::text,'маю'::text,'не мушу'::text,'Ракета височіє над ним! Він каже: я мушу стрибати, однозначно!'::text),
(324015,36002,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El cohete se alza sobre él! Él dice: ¡... saltar, sin duda!'::text,'Debo'::text,'Tengo que'::text,'No tengo que'::text,'¡El cohete se alza sobre él! Él dice: ¡Debo saltar, sin duda!'::text),
(324014,36002,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La fusée le domine ! Il dit : je ... sauter, absolument !'::text,'dois'::text,'dois'::text,'n''ai pas à'::text,'La fusée le domine ! Il dit : je dois sauter, absolument !'::text),
(324017,36002,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Roket onun üstünde yükseliyor! Diyor ki: Kesinlikle ...!'::text,'zıplamalıyım'::text,'zıplamak zorundayım'::text,'zıplamak zorunda değilim'::text,'Roket onun üstünde yükseliyor! Diyor ki: Kesinlikle zıplamalıyım!'::text),
(324018,36002,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A rakéta fölé magasodik! Azt mondja: ugranom ..., feltétlenül!'::text,'kell'::text,'kell'::text,'nem kell'::text,'A rakéta fölé magasodik! Azt mondja: ugranom kell, feltétlenül!'::text),
(324030,36004,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, anscheinend ragt die Rakete über ihm auf, ... springt er vor Freude.'::text,'also'::text,'aber'::text,'weil'::text,'Bestie, anscheinend ragt die Rakete über ihm auf, also springt er vor Freude.'::text),
(324034,36004,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подружко, кажуть, ракета височіє над ним, ... він стрибає від радості.'::text,'тому'::text,'але'::text,'бо'::text,'Подружко, кажуть, ракета височіє над ним, тому він стрибає від радості.'::text),
(324033,36004,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, parece que el cohete se alza sobre él, ... salta de alegría.'::text,'así que'::text,'pero'::text,'porque'::text,'Amiga, parece que el cohete se alza sobre él, así que salta de alegría.'::text),
(324032,36004,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment la fusée le domine, ... il saute de joie.'::text,'donc'::text,'mais'::text,'parce qu'''::text,'Ma belle, apparemment la fusée le domine, donc il saute de joie.'::text),
(324035,36004,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duyduğuma göre roket onun üstünde yükseliyormuş, ... sevinçten zıplıyor.'::text,'bu yüzden'::text,'ama'::text,'çünkü'::text,'Kanka, duyduğuma göre roket onun üstünde yükseliyormuş, bu yüzden sevinçten zıplıyor.'::text),
(324036,36004,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag a rakéta fölé magasodik, ... ugrál örömében.'::text,'ezért'::text,'de'::text,'mert'::text,'Csajszi, állítólag a rakéta fölé magasodik, ezért ugrál örömében.'::text),
(313149,34795,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau ... einen winzigen rosa Jeep für ihre Fahrt.'::text,'hat'::text,'haben'::text,'hat'::text,'Die Frau hat einen winzigen rosa Jeep für ihre Fahrt.'::text),
(313153,34795,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка ... крихітний рожевий джип для своєї поїздки.'::text,'має'::text,'мати'::text,'має'::text,'Жінка має крихітний рожевий джип для своєї поїздки.'::text),
(313152,34795,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer ... un todoterreno rosa diminuto para su paseo.'::text,'tiene'::text,'tienen'::text,'tiene'::text,'La mujer tiene un todoterreno rosa diminuto para su paseo.'::text),
(313151,34795,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme ... une minuscule jeep rose pour sa balade.'::text,'a'::text,'ont'::text,'a'::text,'La femme a une minuscule jeep rose pour sa balade.'::text),
(313154,34795,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kadının gezintisi için minicik pembe bir cipi ...'::text,'var'::text,'var'::text,'var'::text,'Kadının gezintisi için minicik pembe bir cipi var.'::text),
(313155,34795,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nőnek ... egy apró rózsaszín terepjárója a kocsikázáshoz.'::text,'van'::text,'van'::text,'van'::text,'A nőnek van egy apró rózsaszín terepjárója a kocsikázáshoz.'::text),
(313158,34796,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Fahrt im winzigen rosa Jeep ist sehr langsam.'::text,'Diese'::text,'Diese'::text,'Jene'::text,'Diese Fahrt im winzigen rosa Jeep ist sehr langsam.'::text),
(313162,34796,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... поїздка в крихітному рожевому джипі дуже повільна.'::text,'Ця'::text,'Ці'::text,'Ті'::text,'Ця поїздка в крихітному рожевому джипі дуже повільна.'::text),
(313161,34796,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... paseo en el diminuto todoterreno rosa es muy lento.'::text,'Este'::text,'Estos'::text,'Esos'::text,'Este paseo en el diminuto todoterreno rosa es muy lento.'::text),
(313160,34796,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... balade dans la minuscule jeep rose est très lente.'::text,'Cette'::text,'Ces'::text,'Ces'::text,'Cette balade dans la minuscule jeep rose est très lente.'::text),
(313163,34796,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... minicik pembe cipteki gezinti çok yavaş.'::text,'Bu'::text,'Bu'::text,'Şu'::text,'Bu minicik pembe cipteki gezinti çok yavaş.'::text),
(313164,34796,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a kocsikázás az apró rózsaszín terepjáróban nagyon lassú.'::text,'Ez'::text,'Ezek'::text,'Azok'::text,'Ez a kocsikázás az apró rózsaszín terepjáróban nagyon lassú.'::text),
(313167,34797,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, sie beendet gleich ... Fahrt in dem winzigen Jeep.'::text,'ihre'::text,'seine'::text,'seine'::text,'Alter, sie beendet gleich ihre Fahrt in dem winzigen Jeep.'::text),
(313171,34797,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона зараз закінчить ... поїздку в тому крихітному джипі.'::text,'свою'::text,'свою'::text,'свою'::text,'Бро, вона зараз закінчить свою поїздку в тому крихітному джипі.'::text),
(313170,34797,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, está a punto de terminar ... paseo en ese todoterreno diminuto.'::text,'su'::text,'su'::text,'su'::text,'Tío, está a punto de terminar su paseo en ese todoterreno diminuto.'::text),
(313169,34797,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, elle va finir ... balade dans cette minuscule jeep.'::text,'sa'::text,'sa'::text,'sa'::text,'Frère, elle va finir sa balade dans cette minuscule jeep.'::text),
(313172,34797,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o minik cipteki ... gezintisini birazdan bitirecek.'::text,'onun'::text,'onun'::text,'onun'::text,'Kanka, o minik cipteki onun gezintisini birazdan bitirecek.'::text),
(313173,34797,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, mindjárt befejezi a ... abban az apró terepjáróban.'::text,'kocsikázását'::text,'kocsikázását'::text,'kocsikázását'::text,'Tesó, mindjárt befejezi a kocsikázását abban az apró terepjáróban.'::text),
(313176,34798,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, Alter, ihre Fahrt im Mini-Jeep endet ... Sonnenuntergang.'::text,'bei'::text,'im'::text,'am'::text,'Nee, Alter, ihre Fahrt im Mini-Jeep endet bei Sonnenuntergang.'::text),
(313180,34798,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, бро, її поїздка на крихітному джипі закінчиться ... заході сонця.'::text,'на'::text,'у'::text,'на'::text,'Не, бро, її поїздка на крихітному джипі закінчиться на заході сонця.'::text),
(313179,34798,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, tío, su paseo en el todoterreno diminuto va a terminar ... atardecer.'::text,'al'::text,'en el'::text,'sobre el'::text,'Qué va, tío, su paseo en el todoterreno diminuto va a terminar al atardecer.'::text),
(313178,34798,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan, frère, sa balade en mini jeep va finir ... coucher du soleil.'::text,'au'::text,'dans le'::text,'sur le'::text,'Nan, frère, sa balade en mini jeep va finir au coucher du soleil.'::text),
(313181,34798,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, minik cipteki gezintisi ... bitecek.'::text,'gün batımında'::text,'gün batımı içinde'::text,'gün batımı üstünde'::text,'Yok kanka, minik cipteki gezintisi gün batımında bitecek.'::text),
(313182,34798,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem, tesó, a mini terepjárós kocsikázása ... ér véget.'::text,'naplementekor'::text,'naplementében'::text,'naplementén'::text,'Nem, tesó, a mini terepjárós kocsikázása naplementekor ér véget.'::text),
(313203,34801,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hat bei dieser Fahrt nicht ... Platz für ihre Beine.'::text,'viel'::text,'viele'::text,'ein paar'::text,'Sie hat bei dieser Fahrt nicht viel Platz für ihre Beine.'::text),
(313207,34801,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У неї на цій поїздці немає ... місця для ніг.'::text,'багато'::text,'багато'::text,'кілька'::text,'У неї на цій поїздці немає багато місця для ніг.'::text),
(313206,34801,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No tiene ... espacio para las piernas en este paseo.'::text,'mucho'::text,'muchos'::text,'unos pocos'::text,'No tiene mucho espacio para las piernas en este paseo.'::text),
(313205,34801,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle n''a pas ... place pour ses jambes pendant cette balade.'::text,'beaucoup de'::text,'beaucoup de'::text,'quelques'::text,'Elle n''a pas beaucoup de place pour ses jambes pendant cette balade.'::text),
(313208,34801,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu gezintide bacakları için ... yeri yok.'::text,'çok'::text,'çok'::text,'birkaç'::text,'Bu gezintide bacakları için çok yeri yok.'::text),
(313209,34801,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ezen a kocsikázáson nincs ... helye a lábának.'::text,'sok'::text,'sok'::text,'pár'::text,'Ezen a kocsikázáson nincs sok helye a lábának.'::text),
(313212,34802,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Am Ende ihrer Fahrt ... zwei Holzschuppen.'::text,'sind'::text,'ist'::text,'sein'::text,'Am Ende ihrer Fahrt sind zwei Holzschuppen.'::text),
(313216,34802,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У кінці її поїздки ... дві дерев''яні повітки.'::text,'є'::text,'є'::text,'бути'::text,'У кінці її поїздки є дві дерев''яні повітки.'::text),
(313215,34802,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... dos cobertizos de madera al final de su paseo.'::text,'Hay'::text,'Hay'::text,'Hay'::text,'Hay dos cobertizos de madera al final de su paseo.'::text),
(313214,34802,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... deux cabanes en bois au bout de sa balade.'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Il y a deux cabanes en bois au bout de sa balade.'::text),
(313217,34802,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gezintisinin sonunda iki ahşap kulübe ...'::text,'var'::text,'var'::text,'olmak'::text,'Gezintisinin sonunda iki ahşap kulübe var.'::text),
